// Verses for "Name That Book". book must match a name in data/books.js exactly.
// level: 1 = well known, 2 = familiar to regular readers, 3 = deep cut.
window.BOOK_VERSES = [
  // ---------- Law ----------
  { book: 'Genesis', ref: 'Genesis 1:1', level: 1, text: 'In the beginning God created the heaven and the earth.', point: 'Everything starts with God, and that includes your own story.' },
  { book: 'Genesis', ref: 'Genesis 1:27', level: 2, text: 'So God created man in his own image, in the image of God created he him; male and female created he them.', point: 'Every person you meet carries God’s image, which is why every life matters.' },
  { book: 'Genesis', ref: 'Genesis 37:3', level: 2, text: 'Now Israel loved Joseph more than all his children, because he was the son of his old age: and he made him a coat of many colours.', point: 'A family’s favouritism set off Joseph’s hard road, yet God was still writing the story.' },
  { book: 'Genesis', ref: 'Genesis 50:20', level: 3, text: 'But as for you, ye thought evil against me; but God meant it unto good, to bring to pass, as it is this day, to save much people alive.', point: 'God can turn what others meant for harm into rescue, as he did fully at the cross.' },
  { book: 'Genesis', ref: 'Genesis 1:3', level: 1, text: 'And God said, Let there be light: and there was light.', point: 'God’s first spoken words brought light; Jesus later called himself the light of the world.' },
  { book: 'Genesis', ref: 'Genesis 1:31', level: 2, text: 'And God saw every thing that he had made, and, behold, it was very good. And the evening and the morning were the sixth day.', point: 'Creation came from God’s hands very good, and he is still at work making things new.' },
  { book: 'Genesis', ref: 'Genesis 2:7', level: 2, text: 'And the LORD God formed man of the dust of the ground, and breathed into his nostrils the breath of life; and man became a living soul.', point: 'Every breath you take started with God’s own breath.' },
  { book: 'Genesis', ref: 'Genesis 2:18', level: 2, text: 'And the LORD God said, It is not good that the man should be alone; I will make him an help meet for him.', point: 'God made us for relationship, with him and with each other.' },
  { book: 'Genesis', ref: 'Genesis 3:9', level: 3, text: 'And the LORD God called unto Adam, and said unto him, Where art thou?', point: 'After the very first sin, God came looking. He still seeks the lost.' },
  { book: 'Genesis', ref: 'Genesis 3:15', level: 3, text: 'And I will put enmity between thee and the woman, and between thy seed and her seed; it shall bruise thy head, and thou shalt bruise his heel.', point: 'The first hint of the gospel: a Son of the woman would crush the serpent.' },
  { book: 'Genesis', ref: 'Genesis 4:9', level: 2, text: 'And the LORD said unto Cain, Where is Abel thy brother? And he said, I know not: Am I my brother’s keeper?', point: 'Cain dodged the question, but God made it clear: we are meant to care for each other.' },
  { book: 'Genesis', ref: 'Genesis 6:8', level: 2, text: 'But Noah found grace in the eyes of the LORD.', point: 'Before the ark was built, there was grace. Rescue always starts with God’s kindness.' },
  { book: 'Genesis', ref: 'Genesis 9:13', level: 2, text: 'I do set my bow in the cloud, and it shall be for a token of a covenant between me and the earth.', point: 'Next time a rainbow follows the rain, remember that God keeps his promises.' },
  { book: 'Genesis', ref: 'Genesis 12:2', level: 2, text: 'And I will make of thee a great nation, and I will bless thee, and make thy name great; and thou shalt be a blessing:', point: 'Abraham was blessed to bless others, and through his family came Jesus, a blessing for every nation.' },
  { book: 'Genesis', ref: 'Genesis 15:6', level: 3, text: 'And he believed in the LORD; and he counted it to him for righteousness.', point: 'Abraham was put right with God by trusting him, the same way people are today.' },
  { book: 'Genesis', ref: 'Genesis 18:14', level: 2, text: 'Is any thing too hard for the LORD? At the time appointed I will return unto thee, according to the time of life, and Sarah shall have a son.', point: 'Sarah laughed, but God’s question still stands: is anything too hard for him?' },
  { book: 'Genesis', ref: 'Genesis 22:8', level: 3, text: 'And Abraham said, My son, God will provide himself a lamb for a burnt offering: so they went both of them together.', point: 'On that mountain God provided a ram; later he provided his own Son, the Lamb of God.' },
  { book: 'Genesis', ref: 'Genesis 28:16', level: 3, text: 'And Jacob awaked out of his sleep, and he said, Surely the LORD is in this place; and I knew it not.', point: 'God can be close even when you don’t notice him.' },
  { book: 'Genesis', ref: 'Genesis 32:28', level: 3, text: 'And he said, Thy name shall be called no more Jacob, but Israel: for as a prince hast thou power with God and with men, and hast prevailed.', point: 'A night of wrestling with God gave Jacob a new name and a new start.' },
  { book: 'Genesis', ref: 'Genesis 39:2', level: 3, text: 'And the LORD was with Joseph, and he was a prosperous man; and he was in the house of his master the Egyptian.', point: 'Even as a slave far from home, Joseph was not alone.' },
  { book: 'Genesis', ref: 'Genesis 41:16', level: 3, text: 'And Joseph answered Pharaoh, saying, It is not in me: God shall give Pharaoh an answer of peace.', point: 'Joseph gave God the credit instead of taking it for himself.' },
  { book: 'Exodus', ref: 'Exodus 3:14', level: 2, text: 'And God said unto Moses, I AM THAT I AM: and he said, Thus shalt thou say unto the children of Israel, I AM hath sent me unto you.', point: 'God names himself here; Jesus later said, “Before Abraham was, I am.”' },
  { book: 'Exodus', ref: 'Exodus 14:14', level: 2, text: 'The LORD shall fight for you, and ye shall hold your peace.', point: 'At the Red Sea, Israel’s part was to trust while God did the fighting.' },
  { book: 'Exodus', ref: 'Exodus 20:3', level: 1, text: 'Thou shalt have no other gods before me.', point: 'The first commandment: nothing else gets the place in your heart that belongs to God.' },
  { book: 'Exodus', ref: 'Exodus 3:5', level: 2, text: 'And he said, Draw not nigh hither: put off thy shoes from off thy feet, for the place whereon thou standest is holy ground.', point: 'Meeting God is holy ground. It changed Moses for good.' },
  { book: 'Exodus', ref: 'Exodus 4:11', level: 3, text: 'And the LORD said unto him, Who hath made man’s mouth? or who maketh the dumb, or deaf, or the seeing, or the blind? have not I the LORD?', point: 'Moses said he couldn’t speak well; God reminded him who made his mouth.' },
  { book: 'Exodus', ref: 'Exodus 5:1', level: 1, text: 'And afterward Moses and Aaron went in, and told Pharaoh, Thus saith the LORD God of Israel, Let my people go, that they may hold a feast unto me in the wilderness.', point: 'God sets people free so they can worship him, and Jesus came to set captives free.' },
  { book: 'Exodus', ref: 'Exodus 12:13', level: 2, text: 'And the blood shall be to you for a token upon the houses where ye are: and when I see the blood, I will pass over you, and the plague shall not be upon you to destroy you, when I smite the land of Egypt.', point: 'The Passover lamb pointed to Jesus, whose blood covers all who trust him.' },
  { book: 'Exodus', ref: 'Exodus 15:2', level: 3, text: 'The LORD is my strength and song, and he is become my salvation: he is my God, and I will prepare him an habitation; my father’s God, and I will exalt him.', point: 'Israel’s first song after the Red Sea: God is strength, song and salvation.' },
  { book: 'Exodus', ref: 'Exodus 16:4', level: 3, text: 'Then said the LORD unto Moses, Behold, I will rain bread from heaven for you; and the people shall go out and gather a certain rate every day, that I may prove them, whether they will walk in my law, or no.', point: 'Manna came daily. Jesus said he is the true bread from heaven.' },
  { book: 'Exodus', ref: 'Exodus 20:8', level: 1, text: 'Remember the sabbath day, to keep it holy.', point: 'God built rest into the week. Rest is a gift, not a waste of time.' },
  { book: 'Exodus', ref: 'Exodus 20:12', level: 1, text: 'Honour thy father and thy mother: that thy days may be long upon the land which the LORD thy God giveth thee.', point: 'Honouring parents comes with a promise attached.' },
  { book: 'Exodus', ref: 'Exodus 33:14', level: 3, text: 'And he said, My presence shall go with thee, and I will give thee rest.', point: 'What Moses wanted most was God’s presence, and God promised it.' },
  { book: 'Exodus', ref: 'Exodus 34:6', level: 3, text: 'And the LORD passed by before him, and proclaimed, The LORD, The LORD God, merciful and gracious, longsuffering, and abundant in goodness and truth,', point: 'God describes himself: merciful, gracious, patient and full of goodness.' },
  { book: 'Leviticus', ref: 'Leviticus 17:11', level: 3, text: 'For the life of the flesh is in the blood: and I have given it to you upon the altar to make an atonement for your souls…', point: 'The sacrifices pointed ahead to Jesus, whose blood was shed once for all.' },
  { book: 'Leviticus', ref: 'Leviticus 19:2', level: 3, text: 'Speak unto all the congregation of the children of Israel, and say unto them, Ye shall be holy: for I the LORD your God am holy.', point: 'God’s people are called to reflect his character.' },
  { book: 'Leviticus', ref: 'Leviticus 19:18', level: 2, text: 'Thou shalt not avenge, nor bear any grudge against the children of thy people, but thou shalt love thy neighbour as thyself: I am the LORD.', point: 'Jesus called this the second greatest commandment.' },
  { book: 'Leviticus', ref: 'Leviticus 19:32', level: 3, text: 'Thou shalt rise up before the hoary head, and honour the face of the old man, and fear thy God: I am the LORD.', point: 'Respect for elders, like grandma in her compound, is part of honouring God.' },
  { book: 'Leviticus', ref: 'Leviticus 25:10', level: 3, text: 'And ye shall hallow the fiftieth year, and proclaim liberty throughout all the land unto all the inhabitants thereof: it shall be a jubile unto you…', point: 'Every fifty years debts were cancelled; Jesus came to proclaim true liberty.' },
  { book: 'Leviticus', ref: 'Leviticus 26:12', level: 3, text: 'And I will walk among you, and will be your God, and ye shall be my people.', point: 'God’s big plan is to live among his people, and in Jesus he did.' },
  { book: 'Numbers', ref: 'Numbers 6:24-25', level: 2, text: 'The LORD bless thee, and keep thee: The LORD make his face shine upon thee, and be gracious unto thee:', point: 'The priestly blessing shows God’s heart: he wants to bless and keep his people.' },
  { book: 'Numbers', ref: 'Numbers 21:8', level: 3, text: 'And the LORD said unto Moses, Make thee a fiery serpent, and set it upon a pole: and it shall come to pass, that every one that is bitten, when he looketh upon it, shall live.', point: 'Jesus said he would be lifted up like this serpent, so that all who look to him live.' },
  { book: 'Numbers', ref: 'Numbers 6:26', level: 2, text: 'The LORD lift up his countenance upon thee, and give thee peace.', point: 'The priestly blessing ends with peace, the very thing Jesus gives.' },
  { book: 'Numbers', ref: 'Numbers 13:30', level: 3, text: 'And Caleb stilled the people before Moses, and said, Let us go up at once, and possess it; for we are well able to overcome it.', point: 'Ten spies saw giants; Caleb saw God’s promise.' },
  { book: 'Numbers', ref: 'Numbers 14:8', level: 3, text: 'If the LORD delight in us, then he will bring us into this land, and give it us; a land which floweth with milk and honey.', point: 'Joshua and Caleb trusted God’s goodness more than their fears.' },
  { book: 'Numbers', ref: 'Numbers 22:28', level: 2, text: 'And the LORD opened the mouth of the ass, and she said unto Balaam, What have I done unto thee, that thou hast smitten me these three times?', point: 'God can use anything to get our attention, even a talking donkey.' },
  { book: 'Numbers', ref: 'Numbers 23:19', level: 2, text: 'God is not a man, that he should lie; neither the son of man, that he should repent: hath he said, and shall he not do it? or hath he spoken, and shall he not make it good?', point: 'Every promise God makes, he keeps.' },
  { book: 'Numbers', ref: 'Numbers 32:23', level: 3, text: 'But if ye will not do so, behold, ye have sinned against the LORD: and be sure your sin will find you out.', point: 'Hidden sin doesn’t stay hidden; better to bring it into the light.' },
  { book: 'Deuteronomy', ref: 'Deuteronomy 6:4-5', level: 2, text: 'Hear, O Israel: The LORD our God is one LORD: And thou shalt love the LORD thy God with all thine heart, and with all thy soul, and with all thy might.', point: 'Jesus called this the first and greatest commandment.' },
  { book: 'Deuteronomy', ref: 'Deuteronomy 31:6', level: 2, text: 'Be strong and of a good courage, fear not, nor be afraid of them: for the LORD thy God, he it is that doth go with thee; he will not fail thee, nor forsake thee.', point: 'Courage comes from knowing who goes with you, not from how strong you feel.' },
  { book: 'Deuteronomy', ref: 'Deuteronomy 6:6', level: 3, text: 'And these words, which I command thee this day, shall be in thine heart:', point: 'God’s word is meant to live in the heart, not just on a page.' },
  { book: 'Deuteronomy', ref: 'Deuteronomy 8:3', level: 2, text: '…that he might make thee know that man doth not live by bread only, but by every word that proceedeth out of the mouth of the LORD doth man live.', point: 'Jesus quoted this line when he was tempted in the wilderness.' },
  { book: 'Deuteronomy', ref: 'Deuteronomy 28:13', level: 2, text: 'And the LORD shall make thee the head, and not the tail; and thou shalt be above only, and thou shalt not be beneath…', point: 'A promise tied to listening to God and following him.' },
  { book: 'Deuteronomy', ref: 'Deuteronomy 30:19', level: 3, text: '…I have set before you life and death, blessing and cursing: therefore choose life, that both thou and thy seed may live:', point: 'God sets the choice before us and urges: choose life.' },
  { book: 'Deuteronomy', ref: 'Deuteronomy 31:8', level: 3, text: 'And the LORD, he it is that doth go before thee; he will be with thee, he will not fail thee, neither forsake thee: fear not, neither be dismayed.', point: 'God goes ahead of you into tomorrow.' },
  { book: 'Deuteronomy', ref: 'Deuteronomy 33:27', level: 3, text: 'The eternal God is thy refuge, and underneath are the everlasting arms…', point: 'When you feel like you’re falling, there are everlasting arms underneath.' },
  { book: 'Deuteronomy', ref: 'Deuteronomy 34:10', level: 3, text: 'And there arose not a prophet since in Israel like unto Moses, whom the LORD knew face to face,', point: 'Moses was unique, yet he pointed ahead to a greater Prophet: Jesus.' },

  // ---------- History ----------
  { book: 'Joshua', ref: 'Joshua 1:9', level: 1, text: 'Have not I commanded thee? Be strong and of a good courage; be not afraid, neither be thou dismayed: for the LORD thy God is with thee whithersoever thou goest.', point: 'A new leader facing a huge task was told the one thing that mattered: God is with you.' },
  { book: 'Joshua', ref: 'Joshua 24:15', level: 1, text: '…choose you this day whom ye will serve; … but as for me and my house, we will serve the LORD.', point: 'Following God is a choice each person and each home has to make for themselves.' },
  { book: 'Joshua', ref: 'Joshua 1:8', level: 2, text: 'This book of the law shall not depart out of thy mouth; but thou shalt meditate therein day and night, that thou mayest observe to do according to all that is written therein: for then thou shalt make thy way prosperous, and then thou shalt have good success.', point: 'Success, God’s way, starts with soaking in his word.' },
  { book: 'Joshua', ref: 'Joshua 2:21', level: 3, text: 'And she said, According unto your words, so be it. And she sent them away, and they departed: and she bound the scarlet line in the window.', point: 'Rahab’s scarlet cord marked her house for rescue, and she ended up in Jesus’ family line.' },
  { book: 'Joshua', ref: 'Joshua 6:20', level: 2, text: 'So the people shouted when the priests blew with the trumpets: and it came to pass, when the people heard the sound of the trumpet, and the people shouted with a great shout, that the wall fell down flat…', point: 'Jericho fell God’s way, not by battering rams but by obedience.' },
  { book: 'Joshua', ref: 'Joshua 10:13', level: 3, text: 'And the sun stood still, and the moon stayed, until the people had avenged themselves upon their enemies…', point: 'The day the sun stood still showed that God rules even the sky.' },
  { book: 'Joshua', ref: 'Joshua 21:45', level: 3, text: 'There failed not ought of any good thing which the LORD had spoken unto the house of Israel; all came to pass.', point: 'Not one of God’s promises fell to the ground.' },
  { book: 'Judges', ref: 'Judges 16:17', level: 2, text: 'That he told her all his heart, and said unto her, There hath not come a razor upon mine head; for I have been a Nazarite unto God from my mother’s womb…', point: 'Samson’s strength was a gift from God, and he gave away its secret too easily.' },
  { book: 'Judges', ref: 'Judges 21:25', level: 3, text: 'In those days there was no king in Israel: every man did that which was right in his own eyes.', point: 'Doing whatever feels right led to chaos; people needed a true King.' },
  { book: 'Judges', ref: 'Judges 2:10', level: 3, text: '…and there arose another generation after them, which knew not the LORD, nor yet the works which he had done for Israel.', point: 'Faith has to be passed on, or a whole generation can forget.' },
  { book: 'Judges', ref: 'Judges 4:4', level: 3, text: 'And Deborah, a prophetess, the wife of Lapidoth, she judged Israel at that time.', point: 'God raised up a wise woman to lead his people.' },
  { book: 'Judges', ref: 'Judges 6:12', level: 2, text: 'And the angel of the LORD appeared unto him, and said unto him, The LORD is with thee, thou mighty man of valour.', point: 'Gideon was hiding, but God saw who he could become.' },
  { book: 'Judges', ref: 'Judges 7:20', level: 3, text: '…and they cried, The sword of the LORD, and of Gideon.', point: 'Three hundred men, trumpets and torches: God won the battle so no one could boast.' },
  { book: 'Judges', ref: 'Judges 16:30', level: 3, text: 'And Samson said, Let me die with the Philistines. And he bowed himself with all his might; and the house fell upon the lords, and upon all the people that were therein…', point: 'Samson’s last prayer was answered; God used even a broken life.' },
  { book: 'Ruth', ref: 'Ruth 1:16', level: 1, text: 'Intreat me not to leave thee, or to return from following after thee: for whither thou goest, I will go; and where thou lodgest, I will lodge: thy people shall be my people, and thy God my God:', point: 'Loyal love brought a foreigner into God’s family and into the line of Jesus.' },
  { book: 'Ruth', ref: 'Ruth 1:20', level: 3, text: 'And she said unto them, Call me not Naomi, call me Mara: for the Almighty hath dealt very bitterly with me.', point: 'Naomi felt bitter, yet God was quietly preparing joy.' },
  { book: 'Ruth', ref: 'Ruth 2:3', level: 3, text: 'And she went, and came, and gleaned in the field after the reapers: and her hap was to light on a part of the field belonging unto Boaz, who was of the kindred of Elimelech.', point: 'At harvest time, a “chance” field turned out to be God’s plan.' },
  { book: 'Ruth', ref: 'Ruth 2:12', level: 3, text: 'The LORD recompense thy work, and a full reward be given thee of the LORD God of Israel, under whose wings thou art come to trust.', point: 'Ruth found shelter under God’s wings.' },
  { book: 'Ruth', ref: 'Ruth 4:17', level: 3, text: '…and they called his name Obed: he is the father of Jesse, the father of David.', point: 'A foreign widow became great-grandmother of King David, and an ancestor of Jesus.' },
  { book: '1 Samuel', ref: '1 Samuel 16:7', level: 1, text: '…for the LORD seeth not as man seeth; for man looketh on the outward appearance, but the LORD looketh on the heart.', point: 'God chose a young shepherd because he looks deeper than looks or status.' },
  { book: '1 Samuel', ref: '1 Samuel 17:45', level: 1, text: 'Then said David to the Philistine, Thou comest to me with a sword, and with a spear, and with a shield: but I come to thee in the name of the LORD of hosts…', point: 'David’s confidence was in God’s name, not in armour or size.' },
  { book: '1 Samuel', ref: '1 Samuel 1:27', level: 2, text: 'For this child I prayed; and the LORD hath given me my petition which I asked of him:', point: 'Hannah poured out her heart and God heard.' },
  { book: '1 Samuel', ref: '1 Samuel 2:2', level: 3, text: 'There is none holy as the LORD: for there is none beside thee: neither is there any rock like our God.', point: 'Hannah’s song: no one is like our God.' },
  { book: '1 Samuel', ref: '1 Samuel 3:10', level: 1, text: 'And the LORD came, and stood, and called as at other times, Samuel, Samuel. Then Samuel answered, Speak; for thy servant heareth.', point: 'A boy learned to listen to God, and God still speaks to the young.' },
  { book: '1 Samuel', ref: '1 Samuel 15:22', level: 2, text: '…Behold, to obey is better than sacrifice, and to hearken than the fat of rams.', point: 'God wants a listening heart more than big religious gestures.' },
  { book: '1 Samuel', ref: '1 Samuel 17:47', level: 2, text: 'And all this assembly shall know that the LORD saveth not with sword and spear: for the battle is the LORD’s, and he will give you into our hands.', point: 'David knew the battle belonged to God.' },
  { book: '1 Samuel', ref: '1 Samuel 18:1', level: 3, text: '…the soul of Jonathan was knit with the soul of David, and Jonathan loved him as his own soul.', point: 'A prince and a shepherd became true friends. Good friends are a gift.' },
  { book: '1 Samuel', ref: '1 Samuel 30:6', level: 3, text: '…but David encouraged himself in the LORD his God.', point: 'When everyone turned against him, David found strength in God.' },
  { book: '2 Samuel', ref: '2 Samuel 6:14', level: 3, text: 'And David danced before the LORD with all his might; and David was girded with a linen ephod.', point: 'Worship can be wholehearted and joyful, without worrying what others think.' },
  { book: '2 Samuel', ref: '2 Samuel 12:7', level: 3, text: 'And Nathan said to David, Thou art the man.', point: 'A true friend tells you the hard truth, and a humble heart receives it.' },
  { book: '2 Samuel', ref: '2 Samuel 1:19', level: 3, text: 'The beauty of Israel is slain upon thy high places: how are the mighty fallen!', point: 'David grieved for Saul and Jonathan. It is right to mourn.' },
  { book: '2 Samuel', ref: '2 Samuel 7:16', level: 3, text: 'And thine house and thy kingdom shall be established for ever before thee: thy throne shall be established for ever.', point: 'This forever-throne is fulfilled in Jesus, the Son of David.' },
  { book: '2 Samuel', ref: '2 Samuel 9:7', level: 3, text: 'And David said unto him, Fear not: for I will surely shew thee kindness for Jonathan thy father’s sake, and will restore thee all the land of Saul thy father; and thou shalt eat bread at my table continually.', point: 'Mephibosheth got a seat at the king’s table, a picture of grace.' },
  { book: '2 Samuel', ref: '2 Samuel 18:33', level: 3, text: '…O my son Absalom, my son, my son Absalom! would God I had died for thee, O Absalom, my son, my son!', point: 'David wished he could die for his son. God’s Son actually did die for us.' },
  { book: '2 Samuel', ref: '2 Samuel 24:24', level: 3, text: '…neither will I offer burnt offerings unto the LORD my God of that which doth cost me nothing.', point: 'Real worship gives something that matters.' },
  { book: '1 Kings', ref: '1 Kings 17:6', level: 3, text: 'And the ravens brought him bread and flesh in the morning, and bread and flesh in the evening; and he drank of the brook.', point: 'God can provide in the most unexpected ways when you are where he sent you.' },
  { book: '1 Kings', ref: '1 Kings 18:21', level: 2, text: '…How long halt ye between two opinions? if the LORD be God, follow him: but if Baal, then follow him.', point: 'Sitting on the fence is not an option; Elijah called people to decide.' },
  { book: '1 Kings', ref: '1 Kings 19:12', level: 3, text: 'And after the earthquake a fire; but the LORD was not in the fire: and after the fire a still small voice.', point: 'God often speaks quietly, so we need to be still enough to hear.' },
  { book: '1 Kings', ref: '1 Kings 3:9', level: 2, text: 'Give therefore thy servant an understanding heart to judge thy people, that I may discern between good and bad…', point: 'Solomon could ask for anything; he asked for wisdom.' },
  { book: '1 Kings', ref: '1 Kings 3:25', level: 2, text: 'And the king said, Divide the living child in two, and give half to the one, and half to the other.', point: 'Solomon’s surprising test revealed the real mother’s love.' },
  { book: '1 Kings', ref: '1 Kings 8:27', level: 3, text: 'But will God indeed dwell on the earth? behold, the heaven and heaven of heavens cannot contain thee; how much less this house that I have builded?', point: 'Solomon wondered if God would live on earth. In Jesus, he did.' },
  { book: '1 Kings', ref: '1 Kings 17:16', level: 3, text: 'And the barrel of meal wasted not, neither did the cruse of oil fail, according to the word of the LORD, which he spake by Elijah.', point: 'A poor widow shared her last meal and never ran out.' },
  { book: '1 Kings', ref: '1 Kings 18:38', level: 2, text: 'Then the fire of the LORD fell, and consumed the burnt sacrifice, and the wood, and the stones, and the dust, and licked up the water that was in the trench.', point: 'On Mount Carmel, God answered by fire and showed he alone is God.' },
  { book: '1 Kings', ref: '1 Kings 18:44', level: 3, text: 'And it came to pass at the seventh time, that he said, Behold, there ariseth a little cloud out of the sea, like a man’s hand…', point: 'After years of drought, one small cloud meant the rains were coming. Keep praying.' },
  { book: '1 Kings', ref: '1 Kings 19:4', level: 3, text: 'But he himself went a day’s journey into the wilderness, and came and sat down under a juniper tree: and he requested for himself that he might die; and said, It is enough; now, O LORD, take away my life; for I am not better than my fathers.', point: 'Even a great prophet hit rock bottom, and God met him with food, rest and care.' },
  { book: '2 Kings', ref: '2 Kings 2:11', level: 2, text: '…behold, there appeared a chariot of fire, and horses of fire, and parted them both asunder; and Elijah went up by a whirlwind into heaven.', point: 'Elijah never died, a reminder that God has power even over death.' },
  { book: '2 Kings', ref: '2 Kings 5:14', level: 3, text: 'Then went he down, and dipped himself seven times in Jordan, according to the saying of the man of God: and his flesh came again like unto the flesh of a little child, and he was clean.', point: 'Naaman was healed when he humbled himself and simply obeyed.' },
  { book: '2 Kings', ref: '2 Kings 6:16', level: 3, text: 'And he answered, Fear not: for they that be with us are more than they that be with them.', point: 'When you feel outnumbered, remember there is more on God’s side than you can see.' },
  { book: '2 Kings', ref: '2 Kings 2:9', level: 2, text: '…And Elisha said, I pray thee, let a double portion of thy spirit be upon me.', point: 'Elisha asked big, wanting to carry on God’s work.' },
  { book: '2 Kings', ref: '2 Kings 4:2', level: 3, text: 'And Elisha said unto her, What shall I do for thee? tell me, what hast thou in the house? And she said, Thine handmaid hath not any thing in the house, save a pot of oil.', point: 'God started a miracle with the little she already had.' },
  { book: '2 Kings', ref: '2 Kings 6:6', level: 3, text: 'And the man of God said, Where fell it? And he shewed him the place. And he cut down a stick, and cast it in thither; and the iron did swim.', point: 'God cared about a borrowed axe head. Small problems matter to him too.' },
  { book: '2 Kings', ref: '2 Kings 6:17', level: 3, text: 'And Elisha prayed, and said, LORD, I pray thee, open his eyes, that he may see. And the LORD opened the eyes of the young man; and he saw: and, behold, the mountain was full of horses and chariots of fire round about Elisha.', point: 'The servant saw an enemy army; God opened his eyes to a bigger one.' },
  { book: '2 Kings', ref: '2 Kings 20:5', level: 3, text: '…I have heard thy prayer, I have seen thy tears: behold, I will heal thee…', point: 'God noticed Hezekiah’s tears and answered.' },
  { book: '2 Kings', ref: '2 Kings 22:1', level: 3, text: 'Josiah was eight years old when he began to reign, and he reigned thirty and one years in Jerusalem…', point: 'A boy king grew up to lead a nation back to God.' },
  { book: '1 Chronicles', ref: '1 Chronicles 4:10', level: 2, text: 'And Jabez called on the God of Israel, saying, Oh that thou wouldest bless me indeed, and enlarge my coast, and that thine hand might be with me, and that thou wouldest keep me from evil…', point: 'A man with a painful name asked God for more, and God answered.' },
  { book: '1 Chronicles', ref: '1 Chronicles 12:32', level: 3, text: 'And of the children of Issachar, which were men that had understanding of the times, to know what Israel ought to do…', point: 'God values people who understand their times and know what to do.' },
  { book: '1 Chronicles', ref: '1 Chronicles 16:11', level: 3, text: 'Seek the LORD and his strength, seek his face continually.', point: 'Seeking God isn’t a one-time thing; it’s a daily habit.' },
  { book: '1 Chronicles', ref: '1 Chronicles 28:20', level: 3, text: 'And David said to Solomon his son, Be strong and of good courage, and do it: fear not, nor be dismayed: for the LORD God, even my God, will be with thee; he will not fail thee, nor forsake thee…', point: 'A father passed on courage and faith to his son.' },
  { book: '1 Chronicles', ref: '1 Chronicles 29:11', level: 3, text: 'Thine, O LORD, is the greatness, and the power, and the glory, and the victory, and the majesty: for all that is in the heaven and in the earth is thine…', point: 'David’s praise echoes in the ending many know from the Lord’s Prayer.' },
  { book: '1 Chronicles', ref: '1 Chronicles 29:14', level: 3, text: '…for all things come of thee, and of thine own have we given thee.', point: 'Everything we give God was his to start with.' },
  { book: '2 Chronicles', ref: '2 Chronicles 7:14', level: 1, text: 'If my people, which are called by my name, shall humble themselves, and pray, and seek my face, and turn from their wicked ways; then will I hear from heaven, and will forgive their sin, and will heal their land.', point: 'Healing for a nation starts with God’s own people turning back to him.' },
  { book: '2 Chronicles', ref: '2 Chronicles 20:15', level: 3, text: '…Be not afraid nor dismayed by reason of this great multitude; for the battle is not yours, but God’s.', point: 'Some battles are bigger than you, and God never asked you to fight them alone.' },
  { book: '2 Chronicles', ref: '2 Chronicles 5:14', level: 3, text: 'So that the priests could not stand to minister by reason of the cloud: for the glory of the LORD had filled the house of God.', point: 'God’s glory filled the temple; later it was seen in the face of Jesus.' },
  { book: '2 Chronicles', ref: '2 Chronicles 15:7', level: 3, text: 'Be ye strong therefore, and let not your hands be weak: for your work shall be rewarded.', point: 'Faithful work for God is never wasted.' },
  { book: '2 Chronicles', ref: '2 Chronicles 16:9', level: 3, text: 'For the eyes of the LORD run to and fro throughout the whole earth, to shew himself strong in the behalf of them whose heart is perfect toward him…', point: 'God is looking for hearts fully turned toward him.' },
  { book: '2 Chronicles', ref: '2 Chronicles 20:12', level: 3, text: '…neither know we what to do: but our eyes are upon thee.', point: 'When you don’t know what to do, keep your eyes on God.' },
  { book: 'Ezra', ref: 'Ezra 3:11', level: 3, text: '…And all the people shouted with a great shout, when they praised the LORD, because the foundation of the house of the LORD was laid.', point: 'Small beginnings are worth celebrating when God is the one building.' },
  { book: 'Ezra', ref: 'Ezra 7:10', level: 3, text: 'For Ezra had prepared his heart to seek the law of the LORD, and to do it, and to teach in Israel statutes and judgments.', point: 'Study it, live it, then teach it: Ezra’s order still works.' },
  { book: 'Ezra', ref: 'Ezra 8:22', level: 3, text: '…The hand of our God is upon all them for good that seek him; but his power and his wrath is against all them that forsake him.', point: 'Ezra trusted God’s protection instead of asking for soldiers.' },
  { book: 'Ezra', ref: 'Ezra 10:4', level: 3, text: 'Arise; for this matter belongeth unto thee: we also will be with thee: be of good courage, and do it.', point: 'Sometimes a leader just needs friends to say: we’re with you, do it.' },
  { book: 'Nehemiah', ref: 'Nehemiah 2:17', level: 3, text: 'Then said I unto them, Ye see the distress that we are in, how Jerusalem lieth waste, and the gates thereof are burned with fire: come, and let us build up the wall of Jerusalem…', point: 'One man’s prayer and courage got a whole city rebuilding.' },
  { book: 'Nehemiah', ref: 'Nehemiah 8:10', level: 2, text: '…neither be ye sorry; for the joy of the LORD is your strength.', point: 'Joy rooted in God gives strength that circumstances can’t take away.' },
  { book: 'Nehemiah', ref: 'Nehemiah 1:4', level: 3, text: 'And it came to pass, when I heard these words, that I sat down and wept, and mourned certain days, and fasted, and prayed before the God of heaven,', point: 'Nehemiah’s big project started on his knees.' },
  { book: 'Nehemiah', ref: 'Nehemiah 4:6', level: 3, text: 'So built we the wall; and all the wall was joined together unto the half thereof: for the people had a mind to work.', point: 'Teamwork and a willing heart got the wall up.' },
  { book: 'Nehemiah', ref: 'Nehemiah 6:3', level: 3, text: 'And I sent messengers unto them, saying, I am doing a great work, so that I cannot come down: why should the work cease, whilst I leave it, and come down to you?', point: 'Nehemiah refused to be distracted from God’s work.' },
  { book: 'Nehemiah', ref: 'Nehemiah 6:15', level: 3, text: 'So the wall was finished in the twenty and fifth day of the month Elul, in fifty and two days.', point: 'Fifty-two days: what God starts, he helps his people finish.' },
  { book: 'Esther', ref: 'Esther 4:14', level: 1, text: '…and who knoweth whether thou art come to the kingdom for such a time as this?', point: 'Where God has placed you is not an accident; you may be there for a purpose.' },
  { book: 'Esther', ref: 'Esther 4:16', level: 2, text: '…and so will I go in unto the king, which is not according to the law: and if I perish, I perish.', point: 'A young queen risked her life to stand up for her people.' },
  { book: 'Esther', ref: 'Esther 2:17', level: 2, text: 'And the king loved Esther above all the women, and she obtained grace and favour in his sight more than all the virgins; so that he set the royal crown upon her head, and made her queen instead of Vashti.', point: 'An orphan became queen, placed there for a purpose.' },
  { book: 'Esther', ref: 'Esther 3:2', level: 3, text: 'And all the king’s servants, that were in the king’s gate, bowed, and reverenced Haman: for the king had so commanded concerning him. But Mordecai bowed not, nor did him reverence.', point: 'Mordecai stood when everyone else bowed.' },
  { book: 'Esther', ref: 'Esther 6:6', level: 3, text: 'So Haman came in. And the king said unto him, What shall be done unto the man whom the king delighteth to honour? Now Haman thought in his heart, To whom would the king delight to do honour more than to myself?', point: 'Pride set Haman up for a big fall.' },
  { book: 'Esther', ref: 'Esther 7:10', level: 2, text: 'So they hanged Haman on the gallows that he had prepared for Mordecai. Then was the king’s wrath pacified.', point: 'The trap Haman set caught him instead. God protected his people.' },

  // ---------- Poetry ----------
  { book: 'Job', ref: 'Job 1:21', level: 2, text: '…the LORD gave, and the LORD hath taken away; blessed be the name of the LORD.', point: 'Even in deep loss, it is possible to keep worshipping God.' },
  { book: 'Job', ref: 'Job 19:25', level: 2, text: 'For I know that my redeemer liveth, and that he shall stand at the latter day upon the earth:', point: 'In his darkest hour, a suffering man held on to a living Redeemer.' },
  { book: 'Job', ref: 'Job 1:1', level: 1, text: 'There was a man in the land of Uz, whose name was Job; and that man was perfect and upright, and one that feared God, and eschewed evil.', point: 'Job’s story asks the big question: why do good people suffer?' },
  { book: 'Job', ref: 'Job 2:13', level: 3, text: 'So they sat down with him upon the ground seven days and seven nights, and none spake a word unto him: for they saw that his grief was very great.', point: 'Sometimes the best comfort is simply sitting with someone in silence.' },
  { book: 'Job', ref: 'Job 12:10', level: 3, text: 'In whose hand is the soul of every living thing, and the breath of all mankind.', point: 'Every living thing is held in God’s hand.' },
  { book: 'Job', ref: 'Job 13:15', level: 2, text: 'Though he slay me, yet will I trust in him…', point: 'Job’s faith held on even when he couldn’t understand.' },
  { book: 'Job', ref: 'Job 23:10', level: 3, text: 'But he knoweth the way that I take: when he hath tried me, I shall come forth as gold.', point: 'Hard times can refine us like gold in fire.' },
  { book: 'Job', ref: 'Job 38:4', level: 2, text: 'Where wast thou when I laid the foundations of the earth? declare, if thou hast understanding.', point: 'God answered Job by showing him how big God is.' },
  { book: 'Job', ref: 'Job 42:5', level: 3, text: 'I have heard of thee by the hearing of the ear: but now mine eye seeth thee.', point: 'Job went from knowing about God to knowing God.' },
  { book: 'Job', ref: 'Job 42:10', level: 2, text: 'And the LORD turned the captivity of Job, when he prayed for his friends: also the LORD gave Job twice as much as he had before.', point: 'Job’s turnaround came as he prayed for the friends who had hurt him.' },
  { book: 'Psalms', ref: 'Psalm 23:1', level: 1, text: 'The LORD is my shepherd; I shall not want.', point: 'Jesus calls himself the Good Shepherd who gives his life for the sheep.' },
  { book: 'Psalms', ref: 'Psalm 46:10', level: 1, text: 'Be still, and know that I am God: I will be exalted among the heathen, I will be exalted in the earth.', point: 'Sometimes the best response to chaos is to stop and remember who God is.' },
  { book: 'Psalms', ref: 'Psalm 51:10', level: 2, text: 'Create in me a clean heart, O God; and renew a right spirit within me.', point: 'David’s prayer after his sin: only God can make a heart clean again.' },
  { book: 'Psalms', ref: 'Psalm 91:1', level: 2, text: 'He that dwelleth in the secret place of the most High shall abide under the shadow of the Almighty.', point: 'Real safety is found in staying close to God.' },
  { book: 'Psalms', ref: 'Psalm 118:24', level: 1, text: 'This is the day which the LORD hath made; we will rejoice and be glad in it.', point: 'Every day is a gift from God and a reason to rejoice.' },
  { book: 'Psalms', ref: 'Psalm 119:105', level: 1, text: 'Thy word is a lamp unto my feet, and a light unto my path.', point: 'God’s word shows you the next step, even when you can’t see the whole road.' },
  { book: 'Psalms', ref: 'Psalm 121:1-2', level: 1, text: 'I will lift up mine eyes unto the hills, from whence cometh my help. My help cometh from the LORD, which made heaven and earth.', point: 'Help comes from the God who made everything, not from the hills themselves.' },
  { book: 'Psalms', ref: 'Psalm 139:14', level: 1, text: 'I will praise thee; for I am fearfully and wonderfully made: marvellous are thy works; and that my soul knoweth right well.', point: 'You were made with care by God; that is where your worth comes from.' },
  { book: 'Psalms', ref: 'Psalm 1:1', level: 1, text: 'Blessed is the man that walketh not in the counsel of the ungodly, nor standeth in the way of sinners, nor sitteth in the seat of the scornful.', point: 'The very first psalm: who you walk with shapes who you become.' },
  { book: 'Psalms', ref: 'Psalm 1:3', level: 2, text: 'And he shall be like a tree planted by the rivers of water, that bringeth forth his fruit in his season; his leaf also shall not wither; and whatsoever he doeth shall prosper.', point: 'Roots near God’s word keep you green even in the dry season.' },
  { book: 'Psalms', ref: 'Psalm 4:8', level: 3, text: 'I will both lay me down in peace, and sleep: for thou, LORD, only makest me dwell in safety.', point: 'A bedtime prayer: you can sleep because God stays awake.' },
  { book: 'Psalms', ref: 'Psalm 5:3', level: 3, text: 'My voice shalt thou hear in the morning, O LORD; in the morning will I direct my prayer unto thee, and will look up.', point: 'Start the day talking to God, then watch for his answer.' },
  { book: 'Psalms', ref: 'Psalm 8:3-4', level: 2, text: 'When I consider thy heavens, the work of thy fingers, the moon and the stars, which thou hast ordained; What is man, that thou art mindful of him? and the son of man, that thou visitest him?', point: 'The God who made the stars still thinks about you.' },
  { book: 'Psalms', ref: 'Psalm 16:11', level: 2, text: 'Thou wilt shew me the path of life: in thy presence is fulness of joy; at thy right hand there are pleasures for evermore.', point: 'The fullest joy is found close to God.' },
  { book: 'Psalms', ref: 'Psalm 19:1', level: 1, text: 'The heavens declare the glory of God; and the firmament sheweth his handywork.', point: 'A starry night is a sermon without words.' },
  { book: 'Psalms', ref: 'Psalm 19:14', level: 2, text: 'Let the words of my mouth, and the meditation of my heart, be acceptable in thy sight, O LORD, my strength, and my redeemer.', point: 'A prayer for both what we say and what we think.' },
  { book: 'Psalms', ref: 'Psalm 22:1', level: 2, text: 'My God, my God, why hast thou forsaken me? why art thou so far from helping me, and from the words of my roaring?', point: 'Jesus cried the opening words of this psalm from the cross.' },
  { book: 'Psalms', ref: 'Psalm 23:4', level: 1, text: 'Yea, though I walk through the valley of the shadow of death, I will fear no evil: for thou art with me; thy rod and thy staff they comfort me.', point: 'The Shepherd walks with you through the darkest valley.' },
  { book: 'Psalms', ref: 'Psalm 24:1', level: 2, text: 'The earth is the LORD’s, and the fulness thereof; the world, and they that dwell therein.', point: 'Everything and everyone belongs to God.' },
  { book: 'Psalms', ref: 'Psalm 27:1', level: 1, text: 'The LORD is my light and my salvation; whom shall I fear? the LORD is the strength of my life; of whom shall I be afraid?', point: 'With God as your light, fear loses its grip.' },
  { book: 'Psalms', ref: 'Psalm 30:5', level: 2, text: 'For his anger endureth but a moment; in his favour is life: weeping may endure for a night, but joy cometh in the morning.', point: 'Sad nights don’t get the last word; morning is coming.' },
  { book: 'Psalms', ref: 'Psalm 32:8', level: 3, text: 'I will instruct thee and teach thee in the way which thou shalt go: I will guide thee with mine eye.', point: 'God promises to guide you, step by step.' },
  { book: 'Psalms', ref: 'Psalm 34:8', level: 2, text: 'O taste and see that the LORD is good: blessed is the man that trusteth in him.', point: 'Don’t just hear about God’s goodness; try it for yourself.' },
  { book: 'Psalms', ref: 'Psalm 34:18', level: 2, text: 'The LORD is nigh unto them that are of a broken heart; and saveth such as be of a contrite spirit.', point: 'God draws near to the brokenhearted.' },
  { book: 'Psalms', ref: 'Psalm 37:4', level: 1, text: 'Delight thyself also in the LORD; and he shall give thee the desires of thine heart.', point: 'When God is your delight, he reshapes what you desire.' },
  { book: 'Psalms', ref: 'Psalm 37:25', level: 3, text: 'I have been young, and now am old; yet have I not seen the righteous forsaken, nor his seed begging bread.', point: 'An old man’s testimony of God’s faithfulness over a lifetime.' },
  { book: 'Psalms', ref: 'Psalm 40:1', level: 2, text: 'I waited patiently for the LORD; and he inclined unto me, and heard my cry.', point: 'Waiting on God isn’t wasted; he bends down to listen.' },
  { book: 'Psalms', ref: 'Psalm 42:1', level: 2, text: 'As the hart panteth after the water brooks, so panteth my soul after thee, O God.', point: 'Our souls are thirsty for God like a deer for water.' },
  { book: 'Psalms', ref: 'Psalm 46:1', level: 1, text: 'God is our refuge and strength, a very present help in trouble.', point: 'God isn’t far away in trouble; he’s right there.' },
  { book: 'Psalms', ref: 'Psalm 55:22', level: 2, text: 'Cast thy burden upon the LORD, and he shall sustain thee: he shall never suffer the righteous to be moved.', point: 'Hand the heavy load to God; he can carry it.' },
  { book: 'Psalms', ref: 'Psalm 56:3', level: 2, text: 'What time I am afraid, I will trust in thee.', point: 'Fear and trust can meet; choose trust.' },
  { book: 'Psalms', ref: 'Psalm 62:1', level: 3, text: 'Truly my soul waiteth upon God: from him cometh my salvation.', point: 'Rescue comes from God alone.' },
  { book: 'Psalms', ref: 'Psalm 68:5', level: 3, text: 'A father of the fatherless, and a judge of the widows, is God in his holy habitation.', point: 'God takes special care of those who have lost family.' },
  { book: 'Psalms', ref: 'Psalm 73:26', level: 3, text: 'My flesh and my heart faileth: but God is the strength of my heart, and my portion for ever.', point: 'When our strength runs out, God’s doesn’t.' },
  { book: 'Psalms', ref: 'Psalm 84:10', level: 3, text: 'For a day in thy courts is better than a thousand. I had rather be a doorkeeper in the house of my God, than to dwell in the tents of wickedness.', point: 'One day with God beats a thousand anywhere else.' },
  { book: 'Psalms', ref: 'Psalm 90:12', level: 3, text: 'So teach us to number our days, that we may apply our hearts unto wisdom.', point: 'Life is short; use your days wisely.' },
  { book: 'Psalms', ref: 'Psalm 95:1', level: 2, text: 'O come, let us sing unto the LORD: let us make a joyful noise to the rock of our salvation.', point: 'Choir practice or bus ride, any place is good for a joyful song.' },
  { book: 'Psalms', ref: 'Psalm 100:1', level: 1, text: 'Make a joyful noise unto the LORD, all ye lands.', point: 'Worship isn’t meant to be quiet or dull; make some noise.' },
  { book: 'Psalms', ref: 'Psalm 103:12', level: 2, text: 'As far as the east is from the west, so far hath he removed our transgressions from us.', point: 'Forgiven sin is sent so far it can never come back.' },
  { book: 'Psalms', ref: 'Psalm 118:22', level: 3, text: 'The stone which the builders refused is become the head stone of the corner.', point: 'Jesus said this was about him: rejected, yet the cornerstone.' },
  { book: 'Psalms', ref: 'Psalm 119:9', level: 2, text: 'Wherewithal shall a young man cleanse his way? by taking heed thereto according to thy word.', point: 'Staying pure as a young person starts with God’s word.' },
  { book: 'Psalms', ref: 'Psalm 119:11', level: 1, text: 'Thy word have I hid in mine heart, that I might not sin against thee.', point: 'Memorising scripture is like storing up armour.' },
  { book: 'Psalms', ref: 'Psalm 127:1', level: 2, text: 'Except the LORD build the house, they labour in vain that build it: except the LORD keep the city, the watchman waketh but in vain.', point: 'Any plan without God is building on sand.' },
  { book: 'Psalms', ref: 'Psalm 133:1', level: 2, text: 'Behold, how good and how pleasant it is for brethren to dwell together in unity!', point: 'Unity among God’s people is beautiful to him.' },
  { book: 'Psalms', ref: 'Psalm 141:3', level: 3, text: 'Set a watch, O LORD, before my mouth; keep the door of my lips.', point: 'A great prayer before a heated conversation.' },
  { book: 'Psalms', ref: 'Psalm 145:18', level: 3, text: 'The LORD is nigh unto all them that call upon him, to all that call upon him in truth.', point: 'Call on God honestly and he is near.' },
  { book: 'Psalms', ref: 'Psalm 147:3', level: 2, text: 'He healeth the broken in heart, and bindeth up their wounds.', point: 'God is a healer of hearts as well as bodies.' },
  { book: 'Psalms', ref: 'Psalm 150:6', level: 1, text: 'Let every thing that hath breath praise the LORD. Praise ye the LORD.', point: 'The last verse of Psalms: if you’re breathing, praise him.' },
  { book: 'Proverbs', ref: 'Proverbs 1:7', level: 2, text: 'The fear of the LORD is the beginning of knowledge: but fools despise wisdom and instruction.', point: 'True wisdom starts with honouring God.' },
  { book: 'Proverbs', ref: 'Proverbs 3:5-6', level: 1, text: 'Trust in the LORD with all thine heart; and lean not unto thine own understanding. In all thy ways acknowledge him, and he shall direct thy paths.', point: 'When you don’t know the way, trust the One who does.' },
  { book: 'Proverbs', ref: 'Proverbs 15:1', level: 1, text: 'A soft answer turneth away wrath: but grievous words stir up anger.', point: 'How you speak can calm a fight or start one.' },
  { book: 'Proverbs', ref: 'Proverbs 22:6', level: 1, text: 'Train up a child in the way he should go: and when he is old, he will not depart from it.', point: 'What we learn young shapes who we become.' },
  { book: 'Proverbs', ref: 'Proverbs 27:17', level: 3, text: 'Iron sharpeneth iron; so a man sharpeneth the countenance of his friend.', point: 'Good friends make each other better, sometimes by friction.' },
  { book: 'Proverbs', ref: 'Proverbs 4:23', level: 2, text: 'Keep thy heart with all diligence; for out of it are the issues of life.', point: 'Guard your heart; everything else flows from it.' },
  { book: 'Proverbs', ref: 'Proverbs 6:6', level: 1, text: 'Go to the ant, thou sluggard; consider her ways, and be wise:', point: 'Even tiny ants have a lesson on hard work.' },
  { book: 'Proverbs', ref: 'Proverbs 11:25', level: 3, text: 'The liberal soul shall be made fat: and he that watereth shall be watered also himself.', point: 'Generous people end up refreshed themselves.' },
  { book: 'Proverbs', ref: 'Proverbs 12:25', level: 3, text: 'Heaviness in the heart of man maketh it stoop: but a good word maketh it glad.', point: 'A kind word can lift a heavy heart; say it today.' },
  { book: 'Proverbs', ref: 'Proverbs 13:20', level: 3, text: 'He that walketh with wise men shall be wise: but a companion of fools shall be destroyed.', point: 'Choose your friends wisely; you’ll become like them.' },
  { book: 'Proverbs', ref: 'Proverbs 14:12', level: 3, text: 'There is a way which seemeth right unto a man, but the end thereof are the ways of death.', point: 'Feeling right isn’t the same as being right. Jesus is the true way.' },
  { book: 'Proverbs', ref: 'Proverbs 16:3', level: 2, text: 'Commit thy works unto the LORD, and thy thoughts shall be established.', point: 'Hand your plans to God and he steadies them.' },
  { book: 'Proverbs', ref: 'Proverbs 16:9', level: 2, text: 'A man’s heart deviseth his way: but the LORD directeth his steps.', point: 'Make plans, but let God direct the steps.' },
  { book: 'Proverbs', ref: 'Proverbs 16:18', level: 1, text: 'Pride goeth before destruction, and an haughty spirit before a fall.', point: 'Pride trips people up every time.' },
  { book: 'Proverbs', ref: 'Proverbs 17:17', level: 2, text: 'A friend loveth at all times, and a brother is born for adversity.', point: 'Real friends show up in the hard times.' },
  { book: 'Proverbs', ref: 'Proverbs 17:22', level: 2, text: 'A merry heart doeth good like a medicine: but a broken spirit drieth the bones.', point: 'Laughter really is good medicine.' },
  { book: 'Proverbs', ref: 'Proverbs 18:10', level: 2, text: 'The name of the LORD is a strong tower: the righteous runneth into it, and is safe.', point: 'God’s name is a safe place to run.' },
  { book: 'Proverbs', ref: 'Proverbs 18:24', level: 2, text: 'A man that hath friends must shew himself friendly: and there is a friend that sticketh closer than a brother.', point: 'Want friends? Be friendly. And Jesus is the friend who sticks closest.' },
  { book: 'Proverbs', ref: 'Proverbs 19:17', level: 3, text: 'He that hath pity upon the poor lendeth unto the LORD; and that which he hath given will he pay him again.', point: 'Kindness to the poor is like a loan to God himself.' },
  { book: 'Proverbs', ref: 'Proverbs 20:11', level: 3, text: 'Even a child is known by his doings, whether his work be pure, and whether it be right.', point: 'Your actions speak, whatever your age.' },
  { book: 'Proverbs', ref: 'Proverbs 22:1', level: 2, text: 'A good name is rather to be chosen than great riches, and loving favour rather than silver and gold.', point: 'A good reputation is worth more than money.' },
  { book: 'Proverbs', ref: 'Proverbs 25:11', level: 3, text: 'A word fitly spoken is like apples of gold in pictures of silver.', point: 'The right words at the right time are beautiful.' },
  { book: 'Proverbs', ref: 'Proverbs 31:10', level: 2, text: 'Who can find a virtuous woman? for her price is far above rubies.', point: 'Strong character is priceless.' },
  { book: 'Proverbs', ref: 'Proverbs 31:30', level: 2, text: 'Favour is deceitful, and beauty is vain: but a woman that feareth the LORD, she shall be praised.', point: 'Looks fade; a heart for God lasts.' },
  { book: 'Ecclesiastes', ref: 'Ecclesiastes 3:1', level: 1, text: 'To every thing there is a season, and a time to every purpose under the heaven:', point: 'God holds every season of life, the hard ones and the happy ones.' },
  { book: 'Ecclesiastes', ref: 'Ecclesiastes 12:1', level: 2, text: 'Remember now thy Creator in the days of thy youth, while the evil days come not…', point: 'Youth is the perfect time to know God, not something to put off.' },
  { book: 'Ecclesiastes', ref: 'Ecclesiastes 1:9', level: 2, text: 'The thing that hath been, it is that which shall be; and that which is done is that which shall be done: and there is no new thing under the sun.', point: 'Trends repeat; only God gives something truly new.' },
  { book: 'Ecclesiastes', ref: 'Ecclesiastes 3:4', level: 2, text: 'A time to weep, and a time to laugh; a time to mourn, and a time to dance;', point: 'Both tears and dancing have their season.' },
  { book: 'Ecclesiastes', ref: 'Ecclesiastes 3:11', level: 2, text: 'He hath made every thing beautiful in his time: also he hath set the world in their heart, so that no man can find out the work that God maketh from the beginning to the end.', point: 'God makes things beautiful in his timing, not ours.' },
  { book: 'Ecclesiastes', ref: 'Ecclesiastes 4:9', level: 2, text: 'Two are better than one; because they have a good reward for their labour.', point: 'Life goes better with a partner and a team.' },
  { book: 'Ecclesiastes', ref: 'Ecclesiastes 4:12', level: 3, text: 'And if one prevail against him, two shall withstand him; and a threefold cord is not quickly broken.', point: 'Friends together, with God in the middle, are hard to break.' },
  { book: 'Ecclesiastes', ref: 'Ecclesiastes 9:10', level: 3, text: 'Whatsoever thy hand findeth to do, do it with thy might…', point: 'Whatever you do, give it your all.' },
  { book: 'Ecclesiastes', ref: 'Ecclesiastes 11:1', level: 3, text: 'Cast thy bread upon the waters: for thou shalt find it after many days.', point: 'Generosity comes back around in time.' },
  { book: 'Ecclesiastes', ref: 'Ecclesiastes 12:13', level: 3, text: 'Let us hear the conclusion of the whole matter: Fear God, and keep his commandments: for this is the whole duty of man.', point: 'After searching everything, the Preacher’s conclusion: honour God.' },
  { book: 'Song of Solomon', ref: 'Song of Solomon 2:4', level: 3, text: 'He brought me to the banqueting house, and his banner over me was love.', point: 'A love song that also pictures the love Christ has for his people.' },
  { book: 'Song of Solomon', ref: 'Song of Solomon 2:11-12', level: 3, text: 'For, lo, the winter is past, the rain is over and gone; The flowers appear on the earth; the time of the singing of birds is come…', point: 'After the rains, the flowers come. Seasons change.' },
  { book: 'Song of Solomon', ref: 'Song of Solomon 2:15', level: 3, text: 'Take us the foxes, the little foxes, that spoil the vines: for our vines have tender grapes.', point: 'Little problems left alone can spoil good things.' },
  { book: 'Song of Solomon', ref: 'Song of Solomon 8:6', level: 3, text: 'Set me as a seal upon thine heart, as a seal upon thine arm: for love is strong as death…', point: 'Love that is strong as death; Jesus’ love proved even stronger.' },
  { book: 'Song of Solomon', ref: 'Song of Solomon 8:7', level: 3, text: 'Many waters cannot quench love, neither can the floods drown it…', point: 'True love can’t be washed away.' },

  // ---------- Prophets ----------
  { book: 'Isaiah', ref: 'Isaiah 6:8', level: 2, text: 'Also I heard the voice of the Lord, saying, Whom shall I send, and who will go for us? Then said I, Here am I; send me.', point: 'God still asks, “Who will go?” and still uses willing people.' },
  { book: 'Isaiah', ref: 'Isaiah 9:6', level: 1, text: 'For unto us a child is born, unto us a son is given: and the government shall be upon his shoulder: and his name shall be called Wonderful, Counsellor, The mighty God, The everlasting Father, The Prince of Peace.', point: 'Written centuries before Bethlehem, this promise points straight to Jesus.' },
  { book: 'Isaiah', ref: 'Isaiah 40:31', level: 1, text: 'But they that wait upon the LORD shall renew their strength; they shall mount up with wings as eagles; they shall run, and not be weary; and they shall walk, and not faint.', point: 'Strength for the long run comes from waiting on God, not hurrying past him.' },
  { book: 'Isaiah', ref: 'Isaiah 41:10', level: 1, text: 'Fear thou not; for I am with thee: be not dismayed; for I am thy God: I will strengthen thee; yea, I will help thee…', point: 'God’s answer to fear is his presence: “I am with thee.”' },
  { book: 'Isaiah', ref: 'Isaiah 53:5', level: 1, text: 'But he was wounded for our transgressions, he was bruised for our iniquities: the chastisement of our peace was upon him; and with his stripes we are healed.', point: 'A clear picture of Jesus on the cross, written about 700 years earlier.' },
  { book: 'Isaiah', ref: 'Isaiah 1:18', level: 1, text: 'Come now, and let us reason together, saith the LORD: though your sins be as scarlet, they shall be as white as snow; though they be red like crimson, they shall be as wool.', point: 'No stain is too deep for God to wash clean.' },
  { book: 'Isaiah', ref: 'Isaiah 6:3', level: 2, text: 'And one cried unto another, and said, Holy, holy, holy, is the LORD of hosts: the whole earth is full of his glory.', point: 'The angels never get tired of saying how holy God is.' },
  { book: 'Isaiah', ref: 'Isaiah 7:14', level: 2, text: 'Therefore the Lord himself shall give you a sign; Behold, a virgin shall conceive, and bear a son, and shall call his name Immanuel.', point: 'Immanuel means God with us, fulfilled in Jesus.' },
  { book: 'Isaiah', ref: 'Isaiah 12:2', level: 3, text: 'Behold, God is my salvation; I will trust, and not be afraid…', point: 'Trust and fear can’t sit in the same seat.' },
  { book: 'Isaiah', ref: 'Isaiah 26:3', level: 2, text: 'Thou wilt keep him in perfect peace, whose mind is stayed on thee: because he trusteth in thee.', point: 'Peace comes from fixing your mind on God.' },
  { book: 'Isaiah', ref: 'Isaiah 30:21', level: 3, text: 'And thine ears shall hear a word behind thee, saying, This is the way, walk ye in it, when ye turn to the right hand, and when ye turn to the left.', point: 'God guides those who listen.' },
  { book: 'Isaiah', ref: 'Isaiah 40:8', level: 2, text: 'The grass withereth, the flower fadeth: but the word of our God shall stand for ever.', point: 'Everything fades except God’s word.' },
  { book: 'Isaiah', ref: 'Isaiah 40:11', level: 3, text: 'He shall feed his flock like a shepherd: he shall gather the lambs with his arm, and carry them in his bosom…', point: 'God carries the little lambs close, as Jesus the Good Shepherd does.' },
  { book: 'Isaiah', ref: 'Isaiah 43:2', level: 2, text: 'When thou passest through the waters, I will be with thee; and through the rivers, they shall not overflow thee: when thou walkest through the fire, thou shalt not be burned; neither shall the flame kindle upon thee.', point: 'God doesn’t promise no floods or fires; he promises to be with you in them.' },
  { book: 'Isaiah', ref: 'Isaiah 43:19', level: 3, text: 'Behold, I will do a new thing; now it shall spring forth; shall ye not know it? I will even make a way in the wilderness, and rivers in the desert.', point: 'God makes roads where there are none.' },
  { book: 'Isaiah', ref: 'Isaiah 49:16', level: 3, text: 'Behold, I have graven thee upon the palms of my hands…', point: 'You are written on God’s hands; he can’t forget you.' },
  { book: 'Isaiah', ref: 'Isaiah 52:7', level: 3, text: 'How beautiful upon the mountains are the feet of him that bringeth good tidings, that publisheth peace…', point: 'Those who carry the good news of Jesus have beautiful feet.' },
  { book: 'Isaiah', ref: 'Isaiah 53:6', level: 1, text: 'All we like sheep have gone astray; we have turned every one to his own way; and the LORD hath laid on him the iniquity of us all.', point: 'We all wandered, and Jesus carried it all.' },
  { book: 'Isaiah', ref: 'Isaiah 55:1', level: 3, text: 'Ho, every one that thirsteth, come ye to the waters, and he that hath no money; come ye, buy, and eat…', point: 'God’s invitation is free: come and drink.' },
  { book: 'Isaiah', ref: 'Isaiah 55:8', level: 2, text: 'For my thoughts are not your thoughts, neither are your ways my ways, saith the LORD.', point: 'God sees far more than we do.' },
  { book: 'Isaiah', ref: 'Isaiah 61:1', level: 3, text: 'The Spirit of the Lord GOD is upon me; because the LORD hath anointed me to preach good tidings unto the meek…', point: 'Jesus read this in Nazareth and said it was fulfilled in him.' },
  { book: 'Isaiah', ref: 'Isaiah 64:8', level: 3, text: 'But now, O LORD, thou art our father; we are the clay, and thou our potter; and we all are the work of thy hand.', point: 'We are clay in the hands of a loving potter.' },
  { book: 'Jeremiah', ref: 'Jeremiah 1:5', level: 2, text: 'Before I formed thee in the belly I knew thee; and before thou camest forth out of the womb I sanctified thee…', point: 'God knew you and had a purpose for you before you were born.' },
  { book: 'Jeremiah', ref: 'Jeremiah 29:11', level: 1, text: 'For I know the thoughts that I think toward you, saith the LORD, thoughts of peace, and not of evil, to give you an expected end.', point: 'Spoken to exiles far from home: God’s plans for his people are good.' },
  { book: 'Jeremiah', ref: 'Jeremiah 1:7', level: 2, text: 'But the LORD said unto me, Say not, I am a child: for thou shalt go to all that I shall send thee, and whatsoever I command thee thou shalt speak.', point: 'Too young? Not for God.' },
  { book: 'Jeremiah', ref: 'Jeremiah 8:22', level: 3, text: 'Is there no balm in Gilead; is there no physician there?…', point: 'Jeremiah longed for healing; Jesus is the great Physician.' },
  { book: 'Jeremiah', ref: 'Jeremiah 17:7', level: 2, text: 'Blessed is the man that trusteth in the LORD, and whose hope the LORD is.', point: 'Blessed is the one whose hope is God himself.' },
  { book: 'Jeremiah', ref: 'Jeremiah 17:9', level: 2, text: 'The heart is deceitful above all things, and desperately wicked: who can know it?', point: 'We need God to search our hearts, because we can fool ourselves.' },
  { book: 'Jeremiah', ref: 'Jeremiah 18:6', level: 3, text: '…Behold, as the clay is in the potter’s hand, so are ye in mine hand, O house of Israel.', point: 'At the potter’s house, God showed he can reshape a life.' },
  { book: 'Jeremiah', ref: 'Jeremiah 20:9', level: 3, text: '…But his word was in mine heart as a burning fire shut up in my bones, and I was weary with forbearing, and I could not stay.', point: 'God’s word burned in Jeremiah until he had to speak.' },
  { book: 'Jeremiah', ref: 'Jeremiah 29:13', level: 2, text: 'And ye shall seek me, and find me, when ye shall search for me with all your heart.', point: 'God isn’t hiding from those who really look.' },
  { book: 'Jeremiah', ref: 'Jeremiah 31:3', level: 2, text: '…Yea, I have loved thee with an everlasting love: therefore with lovingkindness have I drawn thee.', point: 'God’s love has no start date and no end date.' },
  { book: 'Jeremiah', ref: 'Jeremiah 32:27', level: 2, text: 'Behold, I am the LORD, the God of all flesh: is there any thing too hard for me?', point: 'The answer is still no.' },
  { book: 'Jeremiah', ref: 'Jeremiah 33:3', level: 2, text: 'Call unto me, and I will answer thee, and shew thee great and mighty things, which thou knowest not.', point: 'God invites us to call, and promises to answer.' },
  { book: 'Lamentations', ref: 'Lamentations 3:22-23', level: 2, text: 'It is of the LORD’s mercies that we are not consumed, because his compassions fail not. They are new every morning: great is thy faithfulness.', point: 'Even in a book of grief, God’s mercy shines through every new morning.' },
  { book: 'Lamentations', ref: 'Lamentations 3:24', level: 3, text: 'The LORD is my portion, saith my soul; therefore will I hope in him.', point: 'When everything else is gone, God himself is enough.' },
  { book: 'Lamentations', ref: 'Lamentations 3:25', level: 3, text: 'The LORD is good unto them that wait for him, to the soul that seeketh him.', point: 'Waiting on God is never wasted.' },
  { book: 'Lamentations', ref: 'Lamentations 3:41', level: 3, text: 'Let us lift up our heart with our hands unto God in the heavens.', point: 'Lift your hands, and your heart with them.' },
  { book: 'Ezekiel', ref: 'Ezekiel 36:26', level: 3, text: 'A new heart also will I give you, and a new spirit will I put within you: and I will take away the stony heart out of your flesh…', point: 'God promised to change people from the inside, which he does through Jesus.' },
  { book: 'Ezekiel', ref: 'Ezekiel 37:4', level: 2, text: 'Again he said unto me, Prophesy upon these bones, and say unto them, O ye dry bones, hear the word of the LORD.', point: 'God’s word can bring life even where everything looks dead.' },
  { book: 'Ezekiel', ref: 'Ezekiel 18:32', level: 3, text: 'For I have no pleasure in the death of him that dieth, saith the Lord GOD: wherefore turn yourselves, and live ye.', point: 'God wants people to turn and live.' },
  { book: 'Ezekiel', ref: 'Ezekiel 22:30', level: 3, text: 'And I sought for a man among them, that should make up the hedge, and stand in the gap before me for the land…', point: 'God looks for people who will stand in the gap and pray.' },
  { book: 'Ezekiel', ref: 'Ezekiel 34:16', level: 3, text: 'I will seek that which was lost, and bring again that which was driven away, and will bind up that which was broken, and will strengthen that which was sick…', point: 'God the Shepherd seeks the lost, as Jesus did.' },
  { book: 'Ezekiel', ref: 'Ezekiel 37:10', level: 3, text: 'So I prophesied as he commanded me, and the breath came into them, and they lived, and stood up upon their feet, an exceeding great army.', point: 'Dry bones became an army: God brings dead things to life.' },
  { book: 'Daniel', ref: 'Daniel 3:17', level: 1, text: 'If it be so, our God whom we serve is able to deliver us from the burning fiery furnace, and he will deliver us out of thine hand, O king.', point: 'Three young men refused to bow, trusting God whatever the outcome.' },
  { book: 'Daniel', ref: 'Daniel 5:27', level: 3, text: 'TEKEL; Thou art weighed in the balances, and art found wanting.', point: 'The writing on the wall warned a proud king that God weighs every life.' },
  { book: 'Daniel', ref: 'Daniel 6:22', level: 1, text: 'My God hath sent his angel, and hath shut the lions’ mouths, that they have not hurt me…', point: 'Faithfulness in prayer led to the lions’ den, and God met him there.' },
  { book: 'Daniel', ref: 'Daniel 1:8', level: 2, text: 'But Daniel purposed in his heart that he would not defile himself with the portion of the king’s meat, nor with the wine which he drank…', point: 'A teenager far from home made up his mind to stay faithful.' },
  { book: 'Daniel', ref: 'Daniel 2:22', level: 3, text: 'He revealeth the deep and secret things: he knoweth what is in the darkness, and the light dwelleth with him.', point: 'Nothing is hidden from God.' },
  { book: 'Daniel', ref: 'Daniel 3:18', level: 2, text: 'But if not, be it known unto thee, O king, that we will not serve thy gods, nor worship the golden image which thou hast set up.', point: '“But if not”: faith that holds even if the rescue doesn’t come.' },
  { book: 'Daniel', ref: 'Daniel 3:25', level: 2, text: 'He answered and said, Lo, I see four men loose, walking in the midst of the fire, and they have no hurt; and the form of the fourth is like the Son of God.', point: 'In the fire, they were not alone.' },
  { book: 'Daniel', ref: 'Daniel 6:10', level: 2, text: '…he kneeled upon his knees three times a day, and prayed, and gave thanks before his God, as he did aforetime.', point: 'Daniel kept his prayer habit even when it became illegal.' },
  { book: 'Daniel', ref: 'Daniel 7:13', level: 3, text: 'I saw in the night visions, and, behold, one like the Son of man came with the clouds of heaven…', point: 'Jesus called himself the Son of man, taking this vision as his own.' },
  { book: 'Daniel', ref: 'Daniel 12:3', level: 3, text: 'And they that be wise shall shine as the brightness of the firmament; and they that turn many to righteousness as the stars for ever and ever.', point: 'Those who point others to God shine like stars.' },
  { book: 'Hosea', ref: 'Hosea 4:6', level: 2, text: 'My people are destroyed for lack of knowledge: because thou hast rejected knowledge, I will also reject thee…', point: 'Not knowing God’s word is costly; knowing him is life.' },
  { book: 'Hosea', ref: 'Hosea 6:6', level: 3, text: 'For I desired mercy, and not sacrifice; and the knowledge of God more than burnt offerings.', point: 'Jesus quoted this: God wants a real relationship, not empty ritual.' },
  { book: 'Hosea', ref: 'Hosea 6:1', level: 3, text: 'Come, and let us return unto the LORD: for he hath torn, and he will heal us; he hath smitten, and he will bind us up.', point: 'It’s never too late to come back to God.' },
  { book: 'Hosea', ref: 'Hosea 10:12', level: 3, text: 'Sow to yourselves in righteousness, reap in mercy; break up your fallow ground: for it is time to seek the LORD…', point: 'Like a farmer before planting season, break up hard ground and seek God.' },
  { book: 'Hosea', ref: 'Hosea 11:1', level: 3, text: 'When Israel was a child, then I loved him, and called my son out of Egypt.', point: 'Matthew says this also came true when young Jesus came back from Egypt.' },
  { book: 'Joel', ref: 'Joel 2:28', level: 3, text: 'And it shall come to pass afterward, that I will pour out my spirit upon all flesh; and your sons and your daughters shall prophesy, your old men shall dream dreams, your young men shall see visions:', point: 'Peter said this came true at Pentecost, and it includes the young.' },
  { book: 'Joel', ref: 'Joel 2:13', level: 3, text: 'And rend your heart, and not your garments, and turn unto the LORD your God: for he is gracious and merciful, slow to anger, and of great kindness…', point: 'God wants changed hearts, not just a show.' },
  { book: 'Joel', ref: 'Joel 2:25', level: 2, text: 'And I will restore to you the years that the locust hath eaten…', point: 'God can restore what was lost.' },
  { book: 'Joel', ref: 'Joel 2:32', level: 3, text: 'And it shall come to pass, that whosoever shall call on the name of the LORD shall be delivered…', point: 'Paul quoted this: anyone who calls on the Lord will be saved.' },
  { book: 'Amos', ref: 'Amos 3:3', level: 3, text: 'Can two walk together, except they be agreed?', point: 'Walking with God, and with friends, needs a shared direction.' },
  { book: 'Amos', ref: 'Amos 4:12', level: 3, text: '…prepare to meet thy God, O Israel.', point: 'One day everyone will meet God. Be ready.' },
  { book: 'Amos', ref: 'Amos 5:24', level: 3, text: 'But let judgment run down as waters, and righteousness as a mighty stream.', point: 'God wants justice to flow like a river in flood season.' },
  { book: 'Amos', ref: 'Amos 7:14', level: 3, text: 'Then answered Amos, and said to Amaziah, I was no prophet, neither was I a prophet’s son; but I was an herdman, and a gatherer of sycomore fruit:', point: 'God called an ordinary farmer to speak for him.' },
  { book: 'Amos', ref: 'Amos 8:11', level: 3, text: 'Behold, the days come, saith the Lord GOD, that I will send a famine in the land, not a famine of bread, nor a thirst for water, but of hearing the words of the LORD:', point: 'The worst famine is going without God’s word.' },
  { book: 'Obadiah', ref: 'Obadiah 1:15', level: 3, text: 'For the day of the LORD is near upon all the heathen: as thou hast done, it shall be done unto thee: thy reward shall return upon thine own head.', point: 'The shortest Old Testament book warns that cruelty to others comes back around.' },
  { book: 'Obadiah', ref: 'Obadiah 1:4', level: 3, text: 'Though thou exalt thyself as the eagle, and though thou set thy nest among the stars, thence will I bring thee down, saith the LORD.', point: 'No one is too high for God to bring down.' },
  { book: 'Jonah', ref: 'Jonah 1:12', level: 1, text: 'And he said unto them, Take me up, and cast me forth into the sea; so shall the sea be calm unto you: for I know that for my sake this great tempest is upon you.', point: 'Running from God caused a storm; Jesus later pointed to this prophet’s three days in the fish.' },
  { book: 'Jonah', ref: 'Jonah 3:4', level: 2, text: '…Yet forty days, and Nineveh shall be overthrown.', point: 'A short warning led a whole city to repent, and God showed mercy.' },
  { book: 'Jonah', ref: 'Jonah 1:3', level: 2, text: 'But Jonah rose up to flee unto Tarshish from the presence of the LORD…', point: 'Jonah ran the other way. You can’t outrun God.' },
  { book: 'Jonah', ref: 'Jonah 1:17', level: 1, text: 'Now the LORD had prepared a great fish to swallow up Jonah. And Jonah was in the belly of the fish three days and three nights.', point: 'Jesus said Jonah’s three days pointed to his own three days in the tomb.' },
  { book: 'Jonah', ref: 'Jonah 2:9', level: 3, text: 'But I will sacrifice unto thee with the voice of thanksgiving; I will pay that that I have vowed. Salvation is of the LORD.', point: 'From inside a fish, Jonah learned that rescue belongs to God.' },
  { book: 'Jonah', ref: 'Jonah 4:2', level: 3, text: '…for I knew that thou art a gracious God, and merciful, slow to anger, and of great kindness, and repentest thee of the evil.', point: 'Jonah was upset that God was kind to his enemies. God’s mercy is bigger than ours.' },
  { book: 'Micah', ref: 'Micah 5:2', level: 3, text: 'But thou, Bethlehem Ephratah, though thou be little among the thousands of Judah, yet out of thee shall he come forth unto me that is to be ruler in Israel…', point: 'This prophecy named Jesus’ birthplace hundreds of years ahead.' },
  { book: 'Micah', ref: 'Micah 6:8', level: 2, text: 'He hath shewed thee, O man, what is good; and what doth the LORD require of thee, but to do justly, and to love mercy, and to walk humbly with thy God?', point: 'Faith shows up in fairness, kindness and a humble walk with God.' },
  { book: 'Micah', ref: 'Micah 7:18', level: 3, text: 'Who is a God like unto thee, that pardoneth iniquity, and passeth by the transgression of the remnant of his heritage? he retaineth not his anger for ever, because he delighteth in mercy.', point: 'God delights in mercy. That’s who he is.' },
  { book: 'Micah', ref: 'Micah 7:19', level: 3, text: 'He will turn again, he will have compassion upon us; he will subdue our iniquities; and thou wilt cast all their sins into the depths of the sea.', point: 'Forgiven sins are thrown into the deepest sea.' },
  { book: 'Nahum', ref: 'Nahum 1:7', level: 3, text: 'The LORD is good, a strong hold in the day of trouble; and he knoweth them that trust in him.', point: 'In trouble, God is a safe place and knows each one who trusts him.' },
  { book: 'Nahum', ref: 'Nahum 1:3', level: 3, text: 'The LORD is slow to anger, and great in power, and will not at all acquit the wicked…', point: 'God is patient and powerful, and he is also just.' },
  { book: 'Habakkuk', ref: 'Habakkuk 2:2', level: 2, text: '…Write the vision, and make it plain upon tables, that he may run that readeth it.', point: 'God told the prophet to write it down clearly so others could act on it.' },
  { book: 'Habakkuk', ref: 'Habakkuk 3:17-18', level: 3, text: 'Although the fig tree shall not blossom, neither shall fruit be in the vines; … Yet I will rejoice in the LORD, I will joy in the God of my salvation.', point: 'Joy in God can stand even when everything else fails.' },
  { book: 'Habakkuk', ref: 'Habakkuk 1:2', level: 3, text: 'O LORD, how long shall I cry, and thou wilt not hear!…', point: 'You can bring God your honest questions.' },
  { book: 'Habakkuk', ref: 'Habakkuk 2:4', level: 3, text: '…but the just shall live by his faith.', point: 'Quoted three times in the New Testament: we live by trusting God.' },
  { book: 'Habakkuk', ref: 'Habakkuk 2:14', level: 3, text: 'For the earth shall be filled with the knowledge of the glory of the LORD, as the waters cover the sea.', point: 'One day the whole world will know God’s glory.' },
  { book: 'Habakkuk', ref: 'Habakkuk 3:19', level: 3, text: 'The LORD God is my strength, and he will make my feet like hinds’ feet, and he will make me to walk upon mine high places…', point: 'God gives sure footing on rocky paths.' },
  { book: 'Zephaniah', ref: 'Zephaniah 3:17', level: 3, text: 'The LORD thy God in the midst of thee is mighty; he will save, he will rejoice over thee with joy; he will rest in his love, he will joy over thee with singing.', point: 'Picture it: God singing over you with joy.' },
  { book: 'Zephaniah', ref: 'Zephaniah 2:3', level: 3, text: 'Seek ye the LORD, all ye meek of the earth, which have wrought his judgment; seek righteousness, seek meekness…', point: 'The humble are invited to seek God.' },
  { book: 'Haggai', ref: 'Haggai 2:9', level: 3, text: 'The glory of this latter house shall be greater than of the former, saith the LORD of hosts: and in this place will I give peace, saith the LORD of hosts.', point: 'The smaller rebuilt temple would one day welcome Jesus himself.' },
  { book: 'Haggai', ref: 'Haggai 1:5', level: 3, text: 'Now therefore thus saith the LORD of hosts; Consider your ways.', point: 'Stop and think: where is your life heading?' },
  { book: 'Haggai', ref: 'Haggai 1:6', level: 3, text: 'Ye have sown much, and bring in little; ye eat, but ye have not enough; ye drink, but ye are not filled with drink; ye clothe you, but there is none warm; and he that earneth wages earneth wages to put it into a bag with holes.', point: 'Life without God first is like a money bag with holes.' },
  { book: 'Zechariah', ref: 'Zechariah 4:6', level: 2, text: '…Not by might, nor by power, but by my spirit, saith the LORD of hosts.', point: 'God’s work gets done by his Spirit, not by human muscle.' },
  { book: 'Zechariah', ref: 'Zechariah 9:9', level: 3, text: 'Rejoice greatly, O daughter of Zion; shout, O daughter of Jerusalem: behold, thy King cometh unto thee: he is just, and having salvation; lowly, and riding upon an ass…', point: 'Fulfilled on Palm Sunday when Jesus rode into Jerusalem on a donkey.' },
  { book: 'Zechariah', ref: 'Zechariah 4:10', level: 3, text: 'For who hath despised the day of small things?…', point: 'Small beginnings matter to God.' },
  { book: 'Zechariah', ref: 'Zechariah 8:5', level: 3, text: 'And the streets of the city shall be full of boys and girls playing in the streets thereof.', point: 'God’s picture of a restored city includes children at play.' },
  { book: 'Zechariah', ref: 'Zechariah 12:10', level: 3, text: '…and they shall look upon me whom they have pierced…', point: 'John’s Gospel links this to Jesus, pierced on the cross.' },
  { book: 'Malachi', ref: 'Malachi 3:6', level: 3, text: 'For I am the LORD, I change not; therefore ye sons of Jacob are not consumed.', point: 'God does not change, which is why his mercy holds steady.' },
  { book: 'Malachi', ref: 'Malachi 3:10', level: 1, text: 'Bring ye all the tithes into the storehouse, that there may be meat in mine house, and prove me now herewith, saith the LORD of hosts, if I will not open you the windows of heaven…', point: 'Giving to God is an act of trust in the One who provides.' },
  { book: 'Malachi', ref: 'Malachi 3:1', level: 3, text: 'Behold, I will send my messenger, and he shall prepare the way before me…', point: 'John the Baptist was this messenger, preparing the way for Jesus.' },
  { book: 'Malachi', ref: 'Malachi 3:16', level: 3, text: 'Then they that feared the LORD spake often one to another: and the LORD hearkened, and heard it, and a book of remembrance was written before him…', point: 'God listens when his people encourage each other.' },
  { book: 'Malachi', ref: 'Malachi 4:2', level: 3, text: 'But unto you that fear my name shall the Sun of righteousness arise with healing in his wings…', point: 'The last Old Testament book ends looking for a rising Sun, and Jesus came.' },

  // ---------- Gospels ----------
  { book: 'Matthew', ref: 'Matthew 2:1-2', level: 2, text: '…behold, there came wise men from the east to Jerusalem, Saying, Where is he that is born King of the Jews? for we have seen his star in the east, and are come to worship him.', point: 'People from far nations came to worship Jesus from the very start.' },
  { book: 'Matthew', ref: 'Matthew 5:3', level: 1, text: 'Blessed are the poor in spirit: for theirs is the kingdom of heaven.', point: 'Jesus’ first Beatitude: knowing you need God is where blessing begins.' },
  { book: 'Matthew', ref: 'Matthew 5:14', level: 1, text: 'Ye are the light of the world. A city that is set on an hill cannot be hid.', point: 'Jesus says his followers are meant to shine, not hide.' },
  { book: 'Matthew', ref: 'Matthew 6:33', level: 1, text: 'But seek ye first the kingdom of God, and his righteousness; and all these things shall be added unto you.', point: 'Put God first and trust him with everything else.' },
  { book: 'Matthew', ref: 'Matthew 11:28', level: 1, text: 'Come unto me, all ye that labour and are heavy laden, and I will give you rest.', point: 'Jesus invites the tired and burdened to find rest in him.' },
  { book: 'Matthew', ref: 'Matthew 28:19', level: 1, text: 'Go ye therefore, and teach all nations, baptizing them in the name of the Father, and of the Son, and of the Holy Ghost:', point: 'The risen Jesus sends his followers to every nation, starting right where they live.' },
  { book: 'Matthew', ref: 'Matthew 1:21', level: 1, text: 'And she shall bring forth a son, and thou shalt call his name JESUS: for he shall save his people from their sins.', point: 'His name says what he came to do: save.' },
  { book: 'Matthew', ref: 'Matthew 3:17', level: 2, text: 'And lo a voice from heaven, saying, This is my beloved Son, in whom I am well pleased.', point: 'At Jesus’ baptism, the Father spoke his love out loud.' },
  { book: 'Matthew', ref: 'Matthew 4:4', level: 2, text: 'But he answered and said, It is written, Man shall not live by bread alone, but by every word that proceedeth out of the mouth of God.', point: 'Hungry in the desert, Jesus fought temptation with scripture.' },
  { book: 'Matthew', ref: 'Matthew 4:19', level: 1, text: 'And he saith unto them, Follow me, and I will make you fishers of men.', point: 'Jesus called ordinary fishermen and gave them a new purpose.' },
  { book: 'Matthew', ref: 'Matthew 5:9', level: 1, text: 'Blessed are the peacemakers: for they shall be called the children of God.', point: 'Making peace is what God’s children do.' },
  { book: 'Matthew', ref: 'Matthew 5:13', level: 2, text: 'Ye are the salt of the earth: but if the salt have lost his savour, wherewith shall it be salted?…', point: 'Like salt in the soup pot, followers of Jesus are meant to make a difference.' },
  { book: 'Matthew', ref: 'Matthew 5:16', level: 1, text: 'Let your light so shine before men, that they may see your good works, and glorify your Father which is in heaven.', point: 'Shine so that people notice God, not just you.' },
  { book: 'Matthew', ref: 'Matthew 5:44', level: 2, text: 'But I say unto you, Love your enemies, bless them that curse you, do good to them that hate you, and pray for them which despitefully use you, and persecute you;', point: 'Jesus asks the hardest thing, and he lived it on the cross.' },
  { book: 'Matthew', ref: 'Matthew 6:9', level: 1, text: 'After this manner therefore pray ye: Our Father which art in heaven, Hallowed be thy name.', point: 'Jesus taught us to call God Father.' },
  { book: 'Matthew', ref: 'Matthew 6:34', level: 2, text: 'Take therefore no thought for the morrow: for the morrow shall take thought for the things of itself. Sufficient unto the day is the evil thereof.', point: 'Today’s worries are enough; trust God with tomorrow.' },
  { book: 'Matthew', ref: 'Matthew 7:12', level: 1, text: 'Therefore all things whatsoever ye would that men should do to you, do ye even so to them: for this is the law and the prophets.', point: 'The Golden Rule: treat others how you want to be treated.' },
  { book: 'Matthew', ref: 'Matthew 7:24', level: 2, text: 'Therefore whosoever heareth these sayings of mine, and doeth them, I will liken him unto a wise man, which built his house upon a rock:', point: 'Hearing and doing Jesus’ words is building on rock.' },
  { book: 'Matthew', ref: 'Matthew 9:37', level: 3, text: 'Then saith he unto his disciples, The harvest truly is plenteous, but the labourers are few;', point: 'The fields are ready; Jesus is looking for workers.' },
  { book: 'Matthew', ref: 'Matthew 13:46', level: 3, text: 'Who, when he had found one pearl of great price, went and sold all that he had, and bought it.', point: 'God’s kingdom is worth more than everything else.' },
  { book: 'Matthew', ref: 'Matthew 14:29', level: 2, text: 'And he said, Come. And when Peter was come down out of the ship, he walked on the water, to go to Jesus.', point: 'Peter walked on water while his eyes were on Jesus.' },
  { book: 'Matthew', ref: 'Matthew 16:16', level: 2, text: 'And Simon Peter answered and said, Thou art the Christ, the Son of the living God.', point: 'The most important question: who do you say Jesus is?' },
  { book: 'Matthew', ref: 'Matthew 16:26', level: 2, text: 'For what is a man profited, if he shall gain the whole world, and lose his own soul? or what shall a man give in exchange for his soul?', point: 'Nothing in the world is worth trading your soul for.' },
  { book: 'Matthew', ref: 'Matthew 18:20', level: 1, text: 'For where two or three are gathered together in my name, there am I in the midst of them.', point: 'Even a small youth fellowship has Jesus right in the middle.' },
  { book: 'Matthew', ref: 'Matthew 19:14', level: 2, text: 'But Jesus said, Suffer little children, and forbid them not, to come unto me: for of such is the kingdom of heaven.', point: 'Jesus made time for children when others pushed them away.' },
  { book: 'Matthew', ref: 'Matthew 22:37', level: 2, text: 'Jesus said unto him, Thou shalt love the Lord thy God with all thy heart, and with all thy soul, and with all thy mind.', point: 'Love God with everything: heart, soul and mind.' },
  { book: 'Matthew', ref: 'Matthew 25:40', level: 2, text: '…Verily I say unto you, Inasmuch as ye have done it unto one of the least of these my brethren, ye have done it unto me.', point: 'Kindness to the overlooked is kindness to Jesus himself.' },
  { book: 'Matthew', ref: 'Matthew 26:41', level: 2, text: 'Watch and pray, that ye enter not into temptation: the spirit indeed is willing, but the flesh is weak.', point: 'Said in Gethsemane: prayer is how we stay strong.' },
  { book: 'Matthew', ref: 'Matthew 28:6', level: 1, text: 'He is not here: for he is risen, as he said. Come, see the place where the Lord lay.', point: 'The empty tomb is the best news ever.' },
  { book: 'Matthew', ref: 'Matthew 28:20', level: 2, text: 'Teaching them to observe all things whatsoever I have commanded you: and, lo, I am with you alway, even unto the end of the world. Amen.', point: 'Jesus’ last promise in Matthew: I am with you always.' },
  { book: 'Mark', ref: 'Mark 4:39', level: 2, text: 'And he arose, and rebuked the wind, and said unto the sea, Peace, be still. And the wind ceased, and there was a great calm.', point: 'Jesus has authority over the storms, outside and inside.' },
  { book: 'Mark', ref: 'Mark 9:24', level: 3, text: 'And straightway the father of the child cried out, and said with tears, Lord, I believe; help thou mine unbelief.', point: 'Honest faith mixed with doubt is a prayer Jesus answers.' },
  { book: 'Mark', ref: 'Mark 16:15', level: 1, text: 'And he said unto them, Go ye into all the world, and preach the gospel to every creature.', point: 'The good news about Jesus is meant for everyone, everywhere.' },
  { book: 'Mark', ref: 'Mark 1:35', level: 3, text: 'And in the morning, rising up a great while before day, he went out, and departed into a solitary place, and there prayed.', point: 'Even Jesus made time to be alone with the Father.' },
  { book: 'Mark', ref: 'Mark 2:4', level: 2, text: 'And when they could not come nigh unto him for the press, they uncovered the roof where he was: and when they had broken it up, they let down the bed wherein the sick of the palsy lay.', point: 'Four friends broke through a roof to get their friend to Jesus.' },
  { book: 'Mark', ref: 'Mark 2:17', level: 3, text: '…They that are whole have no need of the physician, but they that are sick: I came not to call the righteous, but sinners to repentance.', point: 'Jesus came for people who know they need help.' },
  { book: 'Mark', ref: 'Mark 5:41', level: 3, text: 'And he took the damsel by the hand, and said unto her, Talitha cumi; which is, being interpreted, Damsel, I say unto thee, arise.', point: 'Jesus spoke gently to a twelve-year-old girl and raised her to life.' },
  { book: 'Mark', ref: 'Mark 6:31', level: 3, text: 'And he said unto them, Come ye yourselves apart into a desert place, and rest a while…', point: 'Jesus cares about his followers getting rest.' },
  { book: 'Mark', ref: 'Mark 10:27', level: 2, text: 'And Jesus looking upon them saith, With men it is impossible, but not with God: for with God all things are possible.', point: 'What’s impossible for us is possible for God.' },
  { book: 'Mark', ref: 'Mark 10:45', level: 2, text: 'For even the Son of man came not to be ministered unto, but to minister, and to give his life a ransom for many.', point: 'Jesus came to serve and to give his life for us.' },
  { book: 'Mark', ref: 'Mark 11:24', level: 3, text: 'Therefore I say unto you, What things soever ye desire, when ye pray, believe that ye receive them, and ye shall have them.', point: 'Jesus calls us to pray with faith.' },
  { book: 'Mark', ref: 'Mark 12:31', level: 2, text: 'And the second is like, namely this, Thou shalt love thy neighbour as thyself. There is none other commandment greater than these.', point: 'Love for God shows up as love for neighbours.' },
  { book: 'Mark', ref: 'Mark 12:42', level: 2, text: 'And there came a certain poor widow, and she threw in two mites, which make a farthing.', point: 'Jesus noticed the smallest gift because it was all she had.' },
  { book: 'Mark', ref: 'Mark 16:6', level: 2, text: '…Be not affrighted: Ye seek Jesus of Nazareth, which was crucified: he is risen; he is not here: behold the place where they laid him.', point: 'The angel’s message: he is risen!' },
  { book: 'Luke', ref: 'Luke 1:37', level: 1, text: 'For with God nothing shall be impossible.', point: 'Said to Mary about a miracle birth: nothing is too hard for God.' },
  { book: 'Luke', ref: 'Luke 2:11', level: 1, text: 'For unto you is born this day in the city of David a Saviour, which is Christ the Lord.', point: 'The angels announced the best news ever to ordinary shepherds.' },
  { book: 'Luke', ref: 'Luke 15:20', level: 2, text: '…But when he was yet a great way off, his father saw him, and had compassion, and ran, and fell on his neck, and kissed him.', point: 'The Father runs to welcome back those who come home.' },
  { book: 'Luke', ref: 'Luke 23:34', level: 2, text: 'Then said Jesus, Father, forgive them; for they know not what they do.', point: 'Even on the cross, Jesus prayed for the people hurting him.' },
  { book: 'Luke', ref: 'Luke 1:38', level: 2, text: 'And Mary said, Behold the handmaid of the Lord; be it unto me according to thy word…', point: 'A young woman said yes to God’s plan.' },
  { book: 'Luke', ref: 'Luke 2:7', level: 1, text: 'And she brought forth her firstborn son, and wrapped him in swaddling clothes, and laid him in a manger; because there was no room for them in the inn.', point: 'The King of kings was born in a humble place.' },
  { book: 'Luke', ref: 'Luke 2:14', level: 1, text: 'Glory to God in the highest, and on earth peace, good will toward men.', point: 'The angels’ song on the night Jesus was born.' },
  { book: 'Luke', ref: 'Luke 2:49', level: 3, text: 'And he said unto them, How is it that ye sought me? wist ye not that I must be about my Father’s business?', point: 'At twelve, Jesus already knew who his Father was.' },
  { book: 'Luke', ref: 'Luke 2:52', level: 2, text: 'And Jesus increased in wisdom and stature, and in favour with God and man.', point: 'Jesus grew up too: in mind, body, faith and friendships.' },
  { book: 'Luke', ref: 'Luke 5:4', level: 3, text: 'Now when he had left speaking, he said unto Simon, Launch out into the deep, and let down your nets for a draught.', point: 'After a night of nothing, obeying Jesus filled the nets.' },
  { book: 'Luke', ref: 'Luke 6:38', level: 2, text: 'Give, and it shall be given unto you; good measure, pressed down, and shaken together, and running over, shall men give into your bosom…', point: 'Like a generous market seller who keeps adding more, God gives back overflowing.' },
  { book: 'Luke', ref: 'Luke 9:23', level: 2, text: 'And he said to them all, If any man will come after me, let him deny himself, and take up his cross daily, and follow me.', point: 'Following Jesus is a daily choice.' },
  { book: 'Luke', ref: 'Luke 10:33', level: 2, text: 'But a certain Samaritan, as he journeyed, came where he was: and when he saw him, he had compassion on him,', point: 'The outsider was the one who stopped to help.' },
  { book: 'Luke', ref: 'Luke 10:41', level: 2, text: 'And Jesus answered and said unto her, Martha, Martha, thou art careful and troubled about many things:', point: 'Busy for Jesus is good; time with Jesus is better.' },
  { book: 'Luke', ref: 'Luke 12:15', level: 3, text: 'And he said unto them, Take heed, and beware of covetousness: for a man’s life consisteth not in the abundance of the things which he possesseth.', point: 'Life is more than what you own.' },
  { book: 'Luke', ref: 'Luke 15:7', level: 2, text: 'I say unto you, that likewise joy shall be in heaven over one sinner that repenteth, more than over ninety and nine just persons, which need no repentance.', point: 'Heaven throws a party when one person comes home.' },
  { book: 'Luke', ref: 'Luke 15:24', level: 2, text: 'For this my son was dead, and is alive again; he was lost, and is found. And they began to be merry.', point: 'The father celebrated his son’s return.' },
  { book: 'Luke', ref: 'Luke 17:15', level: 3, text: 'And one of them, when he saw that he was healed, turned back, and with a loud voice glorified God,', point: 'Ten were healed, only one came back to say thank you.' },
  { book: 'Luke', ref: 'Luke 19:5', level: 1, text: 'And when Jesus came to the place, he looked up, and saw him, and said unto him, Zacchaeus, make haste, and come down; for to day I must abide at thy house.', point: 'Jesus knew Zacchaeus by name and invited himself over.' },
  { book: 'Luke', ref: 'Luke 19:10', level: 2, text: 'For the Son of man is come to seek and to save that which was lost.', point: 'Jesus’ mission in one line.' },
  { book: 'Luke', ref: 'Luke 22:42', level: 2, text: 'Saying, Father, if thou be willing, remove this cup from me: nevertheless not my will, but thine, be done.', point: 'In the garden Jesus chose the Father’s will, for our sake.' },
  { book: 'Luke', ref: 'Luke 23:43', level: 2, text: 'And Jesus said unto him, Verily I say unto thee, To day shalt thou be with me in paradise.', point: 'Even at the last hour, a dying thief found grace.' },
  { book: 'Luke', ref: 'Luke 24:32', level: 3, text: 'And they said one to another, Did not our heart burn within us, while he talked with us by the way, and while he opened to us the scriptures?', point: 'Walking to Emmaus, two friends met the risen Jesus without knowing it.' },
  { book: 'John', ref: 'John 1:1', level: 1, text: 'In the beginning was the Word, and the Word was with God, and the Word was God.', point: 'Jesus, the Word, was there before creation and is God himself.' },
  { book: 'John', ref: 'John 3:16', level: 1, text: 'For God so loved the world, that he gave his only begotten Son, that whosoever believeth in him should not perish, but have everlasting life.', point: 'The whole gospel in one sentence: God’s love, his gift, and our response.' },
  { book: 'John', ref: 'John 8:32', level: 1, text: 'And ye shall know the truth, and the truth shall make you free.', point: 'Jesus is the truth, and knowing him brings real freedom.' },
  { book: 'John', ref: 'John 10:10', level: 1, text: 'The thief cometh not, but for to steal, and to kill, and to destroy: I am come that they might have life, and that they might have it more abundantly.', point: 'Jesus came to give full life, not a smaller one.' },
  { book: 'John', ref: 'John 11:35', level: 1, text: 'Jesus wept.', point: 'The shortest verse shows that Jesus truly feels our grief.' },
  { book: 'John', ref: 'John 14:6', level: 1, text: 'Jesus saith unto him, I am the way, the truth, and the life: no man cometh unto the Father, but by me.', point: 'Jesus doesn’t just show the way to God; he is the way.' },
  { book: 'John', ref: 'John 1:12', level: 2, text: 'But as many as received him, to them gave he power to become the sons of God, even to them that believe on his name:', point: 'Receive Jesus and you become a child of God.' },
  { book: 'John', ref: 'John 1:14', level: 2, text: 'And the Word was made flesh, and dwelt among us, (and we beheld his glory, the glory as of the only begotten of the Father,) full of grace and truth.', point: 'God became a human being and lived among us.' },
  { book: 'John', ref: 'John 1:29', level: 2, text: 'The next day John seeth Jesus coming unto him, and saith, Behold the Lamb of God, which taketh away the sin of the world.', point: 'John pointed to Jesus: the Lamb who takes away sin.' },
  { book: 'John', ref: 'John 1:46', level: 3, text: 'And Nathanael said unto him, Can there any good thing come out of Nazareth? Philip saith unto him, Come and see.', point: 'When people doubt, the best answer is: come and see Jesus.' },
  { book: 'John', ref: 'John 2:5', level: 3, text: 'His mother saith unto the servants, Whatsoever he saith unto you, do it.', point: 'Mary’s advice at the wedding is still good: do whatever Jesus says.' },
  { book: 'John', ref: 'John 3:3', level: 1, text: 'Jesus answered and said unto him, Verily, verily, I say unto thee, Except a man be born again, he cannot see the kingdom of God.', point: 'Jesus told Nicodemus everyone needs a brand new start.' },
  { book: 'John', ref: 'John 3:30', level: 2, text: 'He must increase, but I must decrease.', point: 'John the Baptist was happy to step aside so Jesus could shine.' },
  { book: 'John', ref: 'John 4:14', level: 2, text: 'But whosoever drinketh of the water that I shall give him shall never thirst; but the water that I shall give him shall be in him a well of water springing up into everlasting life.', point: 'At a village well, Jesus offered water that never runs dry.' },
  { book: 'John', ref: 'John 4:24', level: 2, text: 'God is a Spirit: and they that worship him must worship him in spirit and in truth.', point: 'Real worship is about the heart, not the place.' },
  { book: 'John', ref: 'John 6:9', level: 2, text: 'There is a lad here, which hath five barley loaves, and two small fishes: but what are they among so many?', point: 'A boy’s small lunch fed thousands in Jesus’ hands.' },
  { book: 'John', ref: 'John 6:35', level: 1, text: 'And Jesus said unto them, I am the bread of life: he that cometh to me shall never hunger; and he that believeth on me shall never thirst.', point: 'Jesus satisfies the hunger nothing else can.' },
  { book: 'John', ref: 'John 8:12', level: 1, text: 'Then spake Jesus again unto them, saying, I am the light of the world: he that followeth me shall not walk in darkness, but shall have the light of life.', point: 'Follow Jesus and you won’t be stuck in the dark.' },
  { book: 'John', ref: 'John 9:25', level: 2, text: 'He answered and said, Whether he be a sinner or no, I know not: one thing I know, that, whereas I was blind, now I see.', point: 'You don’t need all the answers to tell what Jesus did for you.' },
  { book: 'John', ref: 'John 10:11', level: 1, text: 'I am the good shepherd: the good shepherd giveth his life for the sheep.', point: 'The Good Shepherd laid down his life for his sheep.' },
  { book: 'John', ref: 'John 11:25', level: 1, text: 'Jesus said unto her, I am the resurrection, and the life: he that believeth in me, though he were dead, yet shall he live:', point: 'Jesus said this, then raised Lazarus to prove it.' },
  { book: 'John', ref: 'John 12:24', level: 3, text: 'Verily, verily, I say unto you, Except a corn of wheat fall into the ground and die, it abideth alone: but if it die, it bringeth forth much fruit.', point: 'Like seed in planting season, Jesus’ death brought a great harvest of life.' },
  { book: 'John', ref: 'John 13:34', level: 2, text: 'A new commandment I give unto you, That ye love one another; as I have loved you, that ye also love one another.', point: 'Love each other the way Jesus loves you.' },
  { book: 'John', ref: 'John 13:35', level: 2, text: 'By this shall all men know that ye are my disciples, if ye have love one to another.', point: 'Love is how people recognise Jesus’ followers.' },
  { book: 'John', ref: 'John 14:1', level: 1, text: 'Let not your heart be troubled: ye believe in God, believe also in me.', point: 'Jesus speaks peace to troubled hearts.' },
  { book: 'John', ref: 'John 14:27', level: 2, text: 'Peace I leave with you, my peace I give unto you: not as the world giveth, give I unto you. Let not your heart be troubled, neither let it be afraid.', point: 'Jesus’ peace is different from anything the world offers.' },
  { book: 'John', ref: 'John 15:5', level: 1, text: 'I am the vine, ye are the branches: He that abideth in me, and I in him, the same bringeth forth much fruit: for without me ye can do nothing.', point: 'Stay connected to Jesus and fruit will grow.' },
  { book: 'John', ref: 'John 15:13', level: 1, text: 'Greater love hath no man than this, that a man lay down his life for his friends.', point: 'Jesus said it, then did it.' },
  { book: 'John', ref: 'John 16:33', level: 2, text: '…In the world ye shall have tribulation: but be of good cheer; I have overcome the world.', point: 'Trouble is real, but Jesus has already won.' },
  { book: 'John', ref: 'John 19:30', level: 1, text: 'When Jesus therefore had received the vinegar, he said, It is finished: and he bowed his head, and gave up the ghost.', point: 'It is finished: the price for sin fully paid.' },
  { book: 'John', ref: 'John 20:16', level: 3, text: 'Jesus saith unto her, Mary. She turned herself, and saith unto him, Rabboni; which is to say, Master.', point: 'Mary knew the risen Jesus when he said her name.' },
  { book: 'John', ref: 'John 20:29', level: 2, text: 'Jesus saith unto him, Thomas, because thou hast seen me, thou hast believed: blessed are they that have not seen, and yet have believed.', point: 'Jesus has a blessing for those who believe without seeing, that’s us.' },
  { book: 'John', ref: 'John 21:17', level: 2, text: '…Lord, thou knowest all things; thou knowest that I love thee. Jesus saith unto him, Feed my sheep.', point: 'Peter denied Jesus three times; Jesus restored him three times.' },
  { book: 'John', ref: 'John 21:25', level: 3, text: 'And there are also many other things which Jesus did, the which, if they should be written every one, I suppose that even the world itself could not contain the books that should be written. Amen.', point: 'Jesus did far more than any book could hold.' },

  // ---------- Acts ----------
  { book: 'Acts', ref: 'Acts 1:8', level: 1, text: 'But ye shall receive power, after that the Holy Ghost is come upon you: and ye shall be witnesses unto me both in Jerusalem, and in all Judaea, and in Samaria, and unto the uttermost part of the earth.', point: 'The Spirit gives power to tell the world about Jesus.' },
  { book: 'Acts', ref: 'Acts 2:4', level: 2, text: 'And they were all filled with the Holy Ghost, and began to speak with other tongues, as the Spirit gave them utterance.', point: 'At Pentecost the Spirit came and the church was born.' },
  { book: 'Acts', ref: 'Acts 11:26', level: 3, text: '…And the disciples were called Christians first in Antioch.', point: 'The name “Christian” started here, meaning people who belong to Christ.' },
  { book: 'Acts', ref: 'Acts 16:25', level: 2, text: 'And at midnight Paul and Silas prayed, and sang praises unto God: and the prisoners heard them.', point: 'Worship in a prison cell; others are watching how we respond to hard times.' },
  { book: 'Acts', ref: 'Acts 1:9', level: 2, text: 'And when he had spoken these things, while they beheld, he was taken up; and a cloud received him out of their sight.', point: 'Jesus went up to heaven, and the angels said he will come back the same way.' },
  { book: 'Acts', ref: 'Acts 2:38', level: 2, text: 'Then Peter said unto them, Repent, and be baptized every one of you in the name of Jesus Christ for the remission of sins, and ye shall receive the gift of the Holy Ghost.', point: 'Peter’s answer to the crowd: turn to Jesus.' },
  { book: 'Acts', ref: 'Acts 2:42', level: 2, text: 'And they continued stedfastly in the apostles’ doctrine and fellowship, and in breaking of bread, and in prayers.', point: 'The first church learned, ate, prayed and did life together.' },
  { book: 'Acts', ref: 'Acts 3:6', level: 1, text: 'Then Peter said, Silver and gold have I none; but such as I have give I thee: In the name of Jesus Christ of Nazareth rise up and walk.', point: 'Peter had no money, but he had Jesus’ name.' },
  { book: 'Acts', ref: 'Acts 4:12', level: 2, text: 'Neither is there salvation in any other: for there is none other name under heaven given among men, whereby we must be saved.', point: 'Jesus is the only name that saves.' },
  { book: 'Acts', ref: 'Acts 4:13', level: 3, text: 'Now when they saw the boldness of Peter and John, and perceived that they were unlearned and ignorant men, they marvelled; and they took knowledge of them, that they had been with Jesus.', point: 'Time with Jesus showed in ordinary fishermen.' },
  { book: 'Acts', ref: 'Acts 5:29', level: 2, text: 'Then Peter and the other apostles answered and said, We ought to obey God rather than men.', point: 'When there’s a clash, God comes first.' },
  { book: 'Acts', ref: 'Acts 8:30', level: 3, text: 'And Philip ran thither to him, and heard him read the prophet Esaias, and said, Understandest thou what thou readest?', point: 'A roadside question led a traveller to Jesus.' },
  { book: 'Acts', ref: 'Acts 9:4', level: 1, text: 'And he fell to the earth, and heard a voice saying unto him, Saul, Saul, why persecutest thou me?', point: 'Jesus met his fiercest enemy on the road and turned him into Paul.' },
  { book: 'Acts', ref: 'Acts 9:36', level: 3, text: 'Now there was at Joppa a certain disciple named Tabitha, which by interpretation is called Dorcas: this woman was full of good works and almsdeeds which she did.', point: 'Dorcas was known for the clothes she made for widows.' },
  { book: 'Acts', ref: 'Acts 16:31', level: 2, text: 'And they said, Believe on the Lord Jesus Christ, and thou shalt be saved, and thy house.', point: 'The jailer’s question got the clearest answer.' },
  { book: 'Acts', ref: 'Acts 17:11', level: 3, text: 'These were more noble than those in Thessalonica, in that they received the word with all readiness of mind, and searched the scriptures daily, whether those things were so.', point: 'The Bereans checked everything against scripture.' },
  { book: 'Acts', ref: 'Acts 17:28', level: 3, text: 'For in him we live, and move, and have our being…', point: 'Paul told the Athenians that every breath depends on God.' },
  { book: 'Acts', ref: 'Acts 20:9', level: 3, text: 'And there sat in a window a certain young man named Eutychus, being fallen into a deep sleep…', point: 'A young man dozed off during a long sermon and fell, and God raised him up.' },
  { book: 'Acts', ref: 'Acts 20:35', level: 2, text: '…and to remember the words of the Lord Jesus, how he said, It is more blessed to give than to receive.', point: 'Giving brings a joy that receiving can’t.' },
  { book: 'Acts', ref: 'Acts 27:25', level: 3, text: 'Wherefore, sirs, be of good cheer: for I believe God, that it shall be even as it was told me.', point: 'In a shipwreck storm, Paul trusted God’s word.' },

  // ---------- Letters ----------
  { book: 'Romans', ref: 'Romans 3:23', level: 1, text: 'For all have sinned, and come short of the glory of God;', point: 'Everyone needs a Saviour; nobody is good enough on their own.' },
  { book: 'Romans', ref: 'Romans 5:8', level: 2, text: 'But God commendeth his love toward us, in that, while we were yet sinners, Christ died for us.', point: 'God didn’t wait for us to get better before Jesus died for us.' },
  { book: 'Romans', ref: 'Romans 6:23', level: 1, text: 'For the wages of sin is death; but the gift of God is eternal life through Jesus Christ our Lord.', point: 'Sin earns death, but life with God is a free gift in Jesus.' },
  { book: 'Romans', ref: 'Romans 8:28', level: 1, text: 'And we know that all things work together for good to them that love God, to them who are the called according to his purpose.', point: 'God weaves even painful things into good for those who love him.' },
  { book: 'Romans', ref: 'Romans 10:9', level: 2, text: 'That if thou shalt confess with thy mouth the Lord Jesus, and shalt believe in thine heart that God hath raised him from the dead, thou shalt be saved.', point: 'Salvation is simple: trust Jesus as Lord and believe he rose.' },
  { book: 'Romans', ref: 'Romans 12:2', level: 2, text: 'And be not conformed to this world: but be ye transformed by the renewing of your mind…', point: 'Don’t just copy the crowd; let God reshape how you think.' },
  { book: 'Romans', ref: 'Romans 1:16', level: 1, text: 'For I am not ashamed of the gospel of Christ: for it is the power of God unto salvation to every one that believeth…', point: 'The good news about Jesus is nothing to hide.' },
  { book: 'Romans', ref: 'Romans 5:1', level: 2, text: 'Therefore being justified by faith, we have peace with God through our Lord Jesus Christ:', point: 'Through Jesus we have peace with God.' },
  { book: 'Romans', ref: 'Romans 8:1', level: 2, text: 'There is therefore now no condemnation to them which are in Christ Jesus, who walk not after the flesh, but after the Spirit.', point: 'In Christ, the guilty verdict is gone.' },
  { book: 'Romans', ref: 'Romans 8:31', level: 1, text: 'What shall we then say to these things? If God be for us, who can be against us?', point: 'With God on your side, who can stand against you?' },
  { book: 'Romans', ref: 'Romans 8:39', level: 2, text: 'Nor height, nor depth, nor any other creature, shall be able to separate us from the love of God, which is in Christ Jesus our Lord.', point: 'Nothing can separate you from God’s love in Jesus.' },
  { book: 'Romans', ref: 'Romans 10:13', level: 2, text: 'For whosoever shall call upon the name of the Lord shall be saved.', point: 'Whoever calls, no exceptions.' },
  { book: 'Romans', ref: 'Romans 10:17', level: 2, text: 'So then faith cometh by hearing, and hearing by the word of God.', point: 'Faith grows by hearing God’s word.' },
  { book: 'Romans', ref: 'Romans 12:1', level: 2, text: 'I beseech you therefore, brethren, by the mercies of God, that ye present your bodies a living sacrifice, holy, acceptable unto God, which is your reasonable service.', point: 'Our whole lives become worship.' },
  { book: 'Romans', ref: 'Romans 12:12', level: 3, text: 'Rejoicing in hope; patient in tribulation; continuing instant in prayer;', point: 'Three habits for hard seasons: hope, patience, prayer.' },
  { book: 'Romans', ref: 'Romans 12:15', level: 3, text: 'Rejoice with them that do rejoice, and weep with them that weep.', point: 'Share people’s joys and their tears.' },
  { book: 'Romans', ref: 'Romans 12:21', level: 2, text: 'Be not overcome of evil, but overcome evil with good.', point: 'Answer evil with good and you win.' },
  { book: 'Romans', ref: 'Romans 13:8', level: 3, text: 'Owe no man any thing, but to love one another: for he that loveth another hath fulfilled the law.', point: 'The one debt we always owe is love.' },
  { book: 'Romans', ref: 'Romans 14:12', level: 3, text: 'So then every one of us shall give account of himself to God.', point: 'Each of us answers to God for our own life.' },
  { book: 'Romans', ref: 'Romans 15:13', level: 3, text: 'Now the God of hope fill you with all joy and peace in believing, that ye may abound in hope, through the power of the Holy Ghost.', point: 'God is the God of hope who fills us with joy and peace.' },
  { book: '1 Corinthians', ref: '1 Corinthians 6:19', level: 3, text: 'What? know ye not that your body is the temple of the Holy Ghost which is in you, which ye have of God, and ye are not your own?', point: 'Your body matters to God because his Spirit lives in you.' },
  { book: '1 Corinthians', ref: '1 Corinthians 10:13', level: 2, text: 'There hath no temptation taken you but such as is common to man: but God is faithful, who will not suffer you to be tempted above that ye are able…', point: 'You are not alone in temptation, and God always provides a way out.' },
  { book: '1 Corinthians', ref: '1 Corinthians 13:4', level: 1, text: 'Charity suffereth long, and is kind; charity envieth not; charity vaunteth not itself, is not puffed up,', point: 'This is what real love looks like, and Jesus lived it perfectly.' },
  { book: '1 Corinthians', ref: '1 Corinthians 13:13', level: 1, text: 'And now abideth faith, hope, charity, these three; but the greatest of these is charity.', point: 'Of all the gifts, love lasts longest and matters most.' },
  { book: '1 Corinthians', ref: '1 Corinthians 15:55', level: 3, text: 'O death, where is thy sting? O grave, where is thy victory?', point: 'Because Jesus rose, death has lost its final power.' },
  { book: '1 Corinthians', ref: '1 Corinthians 1:18', level: 2, text: 'For the preaching of the cross is to them that perish foolishness; but unto us which are saved it is the power of God.', point: 'The cross looks weak to some, but it is God’s power.' },
  { book: '1 Corinthians', ref: '1 Corinthians 2:9', level: 2, text: 'But as it is written, Eye hath not seen, nor ear heard, neither have entered into the heart of man, the things which God hath prepared for them that love him.', point: 'God has prepared more than you can imagine.' },
  { book: '1 Corinthians', ref: '1 Corinthians 3:6', level: 2, text: 'I have planted, Apollos watered; but God gave the increase.', point: 'We plant and water; only God makes things grow.' },
  { book: '1 Corinthians', ref: '1 Corinthians 9:24', level: 2, text: 'Know ye not that they which run in a race run all, but one receiveth the prize? So run, that ye may obtain.', point: 'Run your faith race to win.' },
  { book: '1 Corinthians', ref: '1 Corinthians 10:31', level: 2, text: 'Whether therefore ye eat, or drink, or whatsoever ye do, do all to the glory of God.', point: 'Even eating and drinking can honour God.' },
  { book: '1 Corinthians', ref: '1 Corinthians 12:27', level: 3, text: 'Now ye are the body of Christ, and members in particular.', point: 'Every believer is a needed part of Christ’s body.' },
  { book: '1 Corinthians', ref: '1 Corinthians 13:11', level: 2, text: 'When I was a child, I spake as a child, I understood as a child, I thought as a child: but when I became a man, I put away childish things.', point: 'Growing up in faith means growing in love.' },
  { book: '1 Corinthians', ref: '1 Corinthians 14:33', level: 3, text: 'For God is not the author of confusion, but of peace, as in all churches of the saints.', point: 'God brings order and peace, not chaos.' },
  { book: '1 Corinthians', ref: '1 Corinthians 15:4', level: 3, text: 'And that he was buried, and that he rose again the third day according to the scriptures:', point: 'The heart of the gospel: he died, was buried and rose.' },
  { book: '1 Corinthians', ref: '1 Corinthians 15:33', level: 2, text: 'Be not deceived: evil communications corrupt good manners.', point: 'Bad company can wear down good character.' },
  { book: '1 Corinthians', ref: '1 Corinthians 15:58', level: 3, text: 'Therefore, my beloved brethren, be ye stedfast, unmoveable, always abounding in the work of the Lord, forasmuch as ye know that your labour is not in vain in the Lord.', point: 'Because Jesus rose, nothing done for him is wasted.' },
  { book: '1 Corinthians', ref: '1 Corinthians 16:14', level: 3, text: 'Let all your things be done with charity.', point: 'Whatever you do, do it with love.' },
  { book: '2 Corinthians', ref: '2 Corinthians 5:17', level: 1, text: 'Therefore if any man be in Christ, he is a new creature: old things are passed away; behold, all things are become new.', point: 'In Christ your past doesn’t define you; you get a fresh start.' },
  { book: '2 Corinthians', ref: '2 Corinthians 12:9', level: 2, text: 'And he said unto me, My grace is sufficient for thee: for my strength is made perfect in weakness…', point: 'God’s power shows up best in the places where we feel weak.' },
  { book: '2 Corinthians', ref: '2 Corinthians 3:17', level: 3, text: 'Now the Lord is that Spirit: and where the Spirit of the Lord is, there is liberty.', point: 'God’s Spirit brings real freedom.' },
  { book: '2 Corinthians', ref: '2 Corinthians 4:8', level: 3, text: 'We are troubled on every side, yet not distressed; we are perplexed, but not in despair;', point: 'Pressed but not crushed: God holds us together.' },
  { book: '2 Corinthians', ref: '2 Corinthians 4:18', level: 3, text: 'While we look not at the things which are seen, but at the things which are not seen: for the things which are seen are temporal; but the things which are not seen are eternal.', point: 'Keep your eyes on what lasts forever.' },
  { book: '2 Corinthians', ref: '2 Corinthians 5:7', level: 1, text: '(For we walk by faith, not by sight:)', point: 'Trusting God even when you can’t see the road ahead.' },
  { book: '2 Corinthians', ref: '2 Corinthians 5:21', level: 3, text: 'For he hath made him to be sin for us, who knew no sin; that we might be made the righteousness of God in him.', point: 'The great exchange: Jesus took our sin, we receive his righteousness.' },
  { book: '2 Corinthians', ref: '2 Corinthians 6:14', level: 2, text: 'Be ye not unequally yoked together with unbelievers: for what fellowship hath righteousness with unrighteousness?…', point: 'Choose close partnerships carefully.' },
  { book: '2 Corinthians', ref: '2 Corinthians 9:7', level: 2, text: 'Every man according as he purposeth in his heart, so let him give; not grudgingly, or of necessity: for God loveth a cheerful giver.', point: 'God loves a cheerful giver.' },
  { book: '2 Corinthians', ref: '2 Corinthians 9:15', level: 3, text: 'Thanks be unto God for his unspeakable gift.', point: 'Jesus is the gift too great for words.' },
  { book: 'Galatians', ref: 'Galatians 2:20', level: 2, text: 'I am crucified with Christ: nevertheless I live; yet not I, but Christ liveth in me…', point: 'The Christian life is Christ living in and through you.' },
  { book: 'Galatians', ref: 'Galatians 5:22-23', level: 1, text: 'But the fruit of the Spirit is love, joy, peace, longsuffering, gentleness, goodness, faith, Meekness, temperance: against such there is no law.', point: 'These qualities grow in us as the Spirit makes us more like Jesus.' },
  { book: 'Galatians', ref: 'Galatians 6:7', level: 2, text: 'Be not deceived; God is not mocked: for whatsoever a man soweth, that shall he also reap.', point: 'Choices have harvests; what you plant today grows tomorrow.' },
  { book: 'Galatians', ref: 'Galatians 1:10', level: 3, text: 'For do I now persuade men, or God? or do I seek to please men? for if I yet pleased men, I should not be the servant of Christ.', point: 'You can’t live for likes and serve Christ fully.' },
  { book: 'Galatians', ref: 'Galatians 3:28', level: 2, text: 'There is neither Jew nor Greek, there is neither bond nor free, there is neither male nor female: for ye are all one in Christ Jesus.', point: 'In Christ, everyone belongs equally.' },
  { book: 'Galatians', ref: 'Galatians 4:4', level: 3, text: 'But when the fulness of the time was come, God sent forth his Son, made of a woman, made under the law,', point: 'Jesus came at exactly the right time.' },
  { book: 'Galatians', ref: 'Galatians 5:1', level: 3, text: 'Stand fast therefore in the liberty wherewith Christ hath made us free, and be not entangled again with the yoke of bondage.', point: 'Christ set you free; don’t go back to the chains.' },
  { book: 'Galatians', ref: 'Galatians 5:13', level: 3, text: 'For, brethren, ye have been called unto liberty; only use not liberty for an occasion to the flesh, but by love serve one another.', point: 'Freedom in Christ is freedom to serve.' },
  { book: 'Galatians', ref: 'Galatians 6:2', level: 2, text: 'Bear ye one another’s burdens, and so fulfil the law of Christ.', point: 'Help carry each other’s loads.' },
  { book: 'Galatians', ref: 'Galatians 6:9', level: 2, text: 'And let us not be weary in well doing: for in due season we shall reap, if we faint not.', point: 'Keep sowing good; harvest time is coming.' },
  { book: 'Ephesians', ref: 'Ephesians 2:8', level: 1, text: 'For by grace are ye saved through faith; and that not of yourselves: it is the gift of God:', point: 'Salvation is a gift you receive, not a prize you earn.' },
  { book: 'Ephesians', ref: 'Ephesians 4:32', level: 1, text: 'And be ye kind one to another, tenderhearted, forgiving one another, even as God for Christ’s sake hath forgiven you.', point: 'We forgive others because we have been forgiven so much.' },
  { book: 'Ephesians', ref: 'Ephesians 6:1', level: 2, text: 'Children, obey your parents in the Lord: for this is right.', point: 'Honouring parents is part of honouring the Lord.' },
  { book: 'Ephesians', ref: 'Ephesians 6:11', level: 1, text: 'Put on the whole armour of God, that ye may be able to stand against the wiles of the devil.', point: 'Spiritual battles are real, and God gives the armour to stand.' },
  { book: 'Ephesians', ref: 'Ephesians 2:10', level: 2, text: 'For we are his workmanship, created in Christ Jesus unto good works, which God hath before ordained that we should walk in them.', point: 'You are God’s handiwork, made for good works.' },
  { book: 'Ephesians', ref: 'Ephesians 3:20', level: 2, text: 'Now unto him that is able to do exceeding abundantly above all that we ask or think, according to the power that worketh in us,', point: 'God can do far more than you can ask or imagine.' },
  { book: 'Ephesians', ref: 'Ephesians 4:5', level: 3, text: 'One Lord, one faith, one baptism,', point: 'Believers are united around one Lord.' },
  { book: 'Ephesians', ref: 'Ephesians 4:26', level: 2, text: 'Be ye angry, and sin not: let not the sun go down upon your wrath:', point: 'Deal with anger before bedtime.' },
  { book: 'Ephesians', ref: 'Ephesians 4:29', level: 3, text: 'Let no corrupt communication proceed out of your mouth, but that which is good to the use of edifying, that it may minister grace unto the hearers.', point: 'Let your words build people up.' },
  { book: 'Ephesians', ref: 'Ephesians 5:20', level: 3, text: 'Giving thanks always for all things unto God and the Father in the name of our Lord Jesus Christ;', point: 'Make thankfulness a habit.' },
  { book: 'Ephesians', ref: 'Ephesians 6:2', level: 3, text: 'Honour thy father and mother; which is the first commandment with promise;', point: 'The first commandment with a promise attached.' },
  { book: 'Ephesians', ref: 'Ephesians 6:12', level: 2, text: 'For we wrestle not against flesh and blood, but against principalities, against powers, against the rulers of the darkness of this world, against spiritual wickedness in high places.', point: 'People aren’t the real enemy.' },
  { book: 'Ephesians', ref: 'Ephesians 6:17', level: 2, text: 'And take the helmet of salvation, and the sword of the Spirit, which is the word of God:', point: 'God’s word is the sword in our armour.' },
  { book: 'Philippians', ref: 'Philippians 2:10', level: 2, text: 'That at the name of Jesus every knee should bow, of things in heaven, and things in earth, and things under the earth;', point: 'One day all creation will honour Jesus as Lord.' },
  { book: 'Philippians', ref: 'Philippians 4:6', level: 2, text: 'Be careful for nothing; but in every thing by prayer and supplication with thanksgiving let your requests be made known unto God.', point: 'Swap worry for prayer, and add thanks while you’re at it.' },
  { book: 'Philippians', ref: 'Philippians 4:13', level: 1, text: 'I can do all things through Christ which strengtheneth me.', point: 'Written from prison: Christ gives strength for whatever life brings.' },
  { book: 'Philippians', ref: 'Philippians 1:6', level: 2, text: 'Being confident of this very thing, that he which hath begun a good work in you will perform it until the day of Jesus Christ:', point: 'God finishes what he starts in you.' },
  { book: 'Philippians', ref: 'Philippians 1:21', level: 2, text: 'For to me to live is Christ, and to die is gain.', point: 'For Paul, Christ was life itself.' },
  { book: 'Philippians', ref: 'Philippians 2:3', level: 3, text: 'Let nothing be done through strife or vainglory; but in lowliness of mind let each esteem other better than themselves.', point: 'Put others first, the way Jesus did.' },
  { book: 'Philippians', ref: 'Philippians 2:5', level: 3, text: 'Let this mind be in you, which was also in Christ Jesus:', point: 'Think like Jesus: humble and serving.' },
  { book: 'Philippians', ref: 'Philippians 2:14', level: 3, text: 'Do all things without murmurings and disputings:', point: 'No grumbling, even about chores.' },
  { book: 'Philippians', ref: 'Philippians 3:14', level: 2, text: 'I press toward the mark for the prize of the high calling of God in Christ Jesus.', point: 'Keep pressing forward toward the prize.' },
  { book: 'Philippians', ref: 'Philippians 4:4', level: 1, text: 'Rejoice in the Lord alway: and again I say, Rejoice.', point: 'Joy in the Lord is possible in every season.' },
  { book: 'Philippians', ref: 'Philippians 4:7', level: 2, text: 'And the peace of God, which passeth all understanding, shall keep your hearts and minds through Christ Jesus.', point: 'God’s peace guards your heart and mind.' },
  { book: 'Philippians', ref: 'Philippians 4:8', level: 2, text: 'Finally, brethren, whatsoever things are true, whatsoever things are honest, whatsoever things are just, whatsoever things are pure, whatsoever things are lovely, whatsoever things are of good report; if there be any virtue, and if there be any praise, think on these things.', point: 'What you feed your mind shapes your life.' },
  { book: 'Philippians', ref: 'Philippians 4:11', level: 3, text: 'Not that I speak in respect of want: for I have learned, in whatsoever state I am, therewith to be content.', point: 'Contentment is learned, and Christ is the secret.' },
  { book: 'Philippians', ref: 'Philippians 4:19', level: 1, text: 'But my God shall supply all your need according to his riches in glory by Christ Jesus.', point: 'God supplies every need from riches that never run out.' },
  { book: 'Colossians', ref: 'Colossians 3:23', level: 3, text: 'And whatsoever ye do, do it heartily, as to the Lord, and not unto men;', point: 'Schoolwork, chores, jobs: all of it can be done for Jesus.' },
  { book: 'Colossians', ref: 'Colossians 1:17', level: 3, text: 'And he is before all things, and by him all things consist.', point: 'Jesus holds the whole universe together.' },
  { book: 'Colossians', ref: 'Colossians 2:7', level: 3, text: 'Rooted and built up in him, and stablished in the faith, as ye have been taught, abounding therein with thanksgiving.', point: 'Deep roots in Christ keep you standing.' },
  { book: 'Colossians', ref: 'Colossians 3:2', level: 2, text: 'Set your affection on things above, not on things on the earth.', point: 'Fix your heart on heaven.' },
  { book: 'Colossians', ref: 'Colossians 3:13', level: 3, text: 'Forbearing one another, and forgiving one another, if any man have a quarrel against any: even as Christ forgave you, so also do ye.', point: 'Forgive as Christ forgave you.' },
  { book: 'Colossians', ref: 'Colossians 3:16', level: 3, text: 'Let the word of Christ dwell in you richly in all wisdom; teaching and admonishing one another in psalms and hymns and spiritual songs, singing with grace in your hearts to the Lord.', point: 'Choir practice is a way to let God’s word live in you.' },
  { book: 'Colossians', ref: 'Colossians 4:6', level: 3, text: 'Let your speech be alway with grace, seasoned with salt, that ye may know how ye ought to answer every man.', point: 'Gracious words, well seasoned.' },
  { book: 'Colossians', ref: 'Colossians 4:14', level: 3, text: 'Luke, the beloved physician, and Demas, greet you.', point: 'Luke the doctor wrote a Gospel and the book of Acts.' },
  { book: '1 Thessalonians', ref: '1 Thessalonians 4:16', level: 2, text: 'For the Lord himself shall descend from heaven with a shout, with the voice of the archangel, and with the trump of God: and the dead in Christ shall rise first:', point: 'Jesus is coming back, and death is not the end for believers.' },
  { book: '1 Thessalonians', ref: '1 Thessalonians 5:17', level: 1, text: 'Pray without ceasing.', point: 'Prayer is meant to be an ongoing conversation with God.' },
  { book: '1 Thessalonians', ref: '1 Thessalonians 4:11', level: 3, text: 'And that ye study to be quiet, and to do your own business, and to work with your own hands, as we commanded you;', point: 'A quiet, hardworking life honours God.' },
  { book: '1 Thessalonians', ref: '1 Thessalonians 5:11', level: 3, text: 'Wherefore comfort yourselves together, and edify one another, even as also ye do.', point: 'Keep encouraging each other.' },
  { book: '1 Thessalonians', ref: '1 Thessalonians 5:16', level: 2, text: 'Rejoice evermore.', point: 'Two words, one big command: keep rejoicing.' },
  { book: '1 Thessalonians', ref: '1 Thessalonians 5:18', level: 1, text: 'In every thing give thanks: for this is the will of God in Christ Jesus concerning you.', point: 'Thankfulness in every situation is God’s will.' },
  { book: '1 Thessalonians', ref: '1 Thessalonians 5:21', level: 3, text: 'Prove all things; hold fast that which is good.', point: 'Test everything; keep what’s good.' },
  { book: '2 Thessalonians', ref: '2 Thessalonians 3:10', level: 3, text: '…that if any would not work, neither should he eat.', point: 'Faith doesn’t make us lazy; honest work honours God.' },
  { book: '2 Thessalonians', ref: '2 Thessalonians 3:3', level: 3, text: 'But the Lord is faithful, who shall stablish you, and keep you from evil.', point: 'The Lord is faithful to keep you.' },
  { book: '2 Thessalonians', ref: '2 Thessalonians 3:16', level: 3, text: 'Now the Lord of peace himself give you peace always by all means. The Lord be with you all.', point: 'Peace always, in every way, from the Lord of peace.' },
  { book: '1 Timothy', ref: '1 Timothy 4:12', level: 1, text: 'Let no man despise thy youth; but be thou an example of the believers, in word, in conversation, in charity, in spirit, in faith, in purity.', point: 'Being young is no reason to wait; you can lead by example now.' },
  { book: '1 Timothy', ref: '1 Timothy 1:15', level: 2, text: 'This is a faithful saying, and worthy of all acceptation, that Christ Jesus came into the world to save sinners; of whom I am chief.', point: 'Paul called himself the worst sinner, and Jesus saved him.' },
  { book: '1 Timothy', ref: '1 Timothy 2:5', level: 2, text: 'For there is one God, and one mediator between God and men, the man Christ Jesus;', point: 'Jesus is the one bridge between God and us.' },
  { book: '1 Timothy', ref: '1 Timothy 4:8', level: 3, text: 'For bodily exercise profiteth little: but godliness is profitable unto all things, having promise of the life that now is, and of that which is to come.', point: 'Train your body, but train your soul even more.' },
  { book: '1 Timothy', ref: '1 Timothy 6:6', level: 2, text: 'But godliness with contentment is great gain.', point: 'Being content with God is real wealth.' },
  { book: '1 Timothy', ref: '1 Timothy 6:10', level: 1, text: 'For the love of money is the root of all evil: which while some coveted after, they have erred from the faith, and pierced themselves through with many sorrows.', point: 'Money isn’t evil; loving it is the trap.' },
  { book: '1 Timothy', ref: '1 Timothy 6:12', level: 2, text: 'Fight the good fight of faith, lay hold on eternal life, whereunto thou art also called…', point: 'Faith is worth fighting for.' },
  { book: '2 Timothy', ref: '2 Timothy 1:7', level: 1, text: 'For God hath not given us the spirit of fear; but of power, and of love, and of a sound mind.', point: 'Fear is not from God; he gives power, love and a clear mind.' },
  { book: '2 Timothy', ref: '2 Timothy 3:16', level: 2, text: 'All scripture is given by inspiration of God, and is profitable for doctrine, for reproof, for correction, for instruction in righteousness:', point: 'The Bible is God-breathed and useful for every part of life.' },
  { book: '2 Timothy', ref: '2 Timothy 4:7', level: 2, text: 'I have fought a good fight, I have finished my course, I have kept the faith:', point: 'Paul’s goal was to finish well, and that can be ours too.' },
  { book: '2 Timothy', ref: '2 Timothy 1:5', level: 3, text: 'When I call to remembrance the unfeigned faith that is in thee, which dwelt first in thy grandmother Lois, and thy mother Eunice; and I am persuaded that in thee also.', point: 'Timothy’s faith was passed down from his grandma and mum.' },
  { book: '2 Timothy', ref: '2 Timothy 2:3', level: 3, text: 'Thou therefore endure hardness, as a good soldier of Jesus Christ.', point: 'Following Jesus takes endurance.' },
  { book: '2 Timothy', ref: '2 Timothy 2:15', level: 2, text: 'Study to shew thyself approved unto God, a workman that needeth not to be ashamed, rightly dividing the word of truth.', point: 'Study the Bible carefully, like a skilled worker.' },
  { book: '2 Timothy', ref: '2 Timothy 2:22', level: 3, text: 'Flee also youthful lusts: but follow righteousness, faith, charity, peace, with them that call on the Lord out of a pure heart.', point: 'Run from temptation and run with good friends.' },
  { book: '2 Timothy', ref: '2 Timothy 3:15', level: 3, text: 'And that from a child thou hast known the holy scriptures, which are able to make thee wise unto salvation through faith which is in Christ Jesus.', point: 'Scripture learned young leads to Jesus.' },
  { book: '2 Timothy', ref: '2 Timothy 4:2', level: 3, text: 'Preach the word; be instant in season, out of season; reprove, rebuke, exhort with all longsuffering and doctrine.', point: 'Be ready to share God’s word any time.' },
  { book: 'Titus', ref: 'Titus 3:5', level: 3, text: 'Not by works of righteousness which we have done, but according to his mercy he saved us…', point: 'God saves us because of his mercy, not our good works.' },
  { book: 'Titus', ref: 'Titus 1:2', level: 3, text: 'In hope of eternal life, which God, that cannot lie, promised before the world began;', point: 'God, who cannot lie, promised eternal life.' },
  { book: 'Titus', ref: 'Titus 2:7', level: 3, text: 'In all things shewing thyself a pattern of good works: in doctrine shewing uncorruptness, gravity, sincerity,', point: 'Be an example others can follow.' },
  { book: 'Titus', ref: 'Titus 2:11', level: 3, text: 'For the grace of God that bringeth salvation hath appeared to all men,', point: 'God’s grace has appeared for everyone, in Jesus.' },
  { book: 'Philemon', ref: 'Philemon 1:10', level: 3, text: 'I beseech thee for my son Onesimus, whom I have begotten in my bonds:', point: 'Paul pleaded for a runaway slave, now a brother in Christ.' },
  { book: 'Philemon', ref: 'Philemon 1:7', level: 3, text: 'For we have great joy and consolation in thy love, because the bowels of the saints are refreshed by thee, brother.', point: 'Philemon refreshed people’s hearts. You can too.' },
  { book: 'Philemon', ref: 'Philemon 1:16', level: 3, text: 'Not now as a servant, but above a servant, a brother beloved, specially to me, but how much more unto thee, both in the flesh, and in the Lord?', point: 'In Christ, a runaway became a beloved brother.' },
  { book: 'Hebrews', ref: 'Hebrews 4:12', level: 2, text: 'For the word of God is quick, and powerful, and sharper than any twoedged sword…', point: 'God’s word is alive and reaches the deepest parts of us.' },
  { book: 'Hebrews', ref: 'Hebrews 11:1', level: 1, text: 'Now faith is the substance of things hoped for, the evidence of things not seen.', point: 'Faith is confident trust in what God has promised.' },
  { book: 'Hebrews', ref: 'Hebrews 11:6', level: 2, text: 'But without faith it is impossible to please him: for he that cometh to God must believe that he is, and that he is a rewarder of them that diligently seek him.', point: 'God rewards those who truly seek him.' },
  { book: 'Hebrews', ref: 'Hebrews 4:15', level: 2, text: 'For we have not an high priest which cannot be touched with the feeling of our infirmities; but was in all points tempted like as we are, yet without sin.', point: 'Jesus understands temptation because he faced it.' },
  { book: 'Hebrews', ref: 'Hebrews 4:16', level: 2, text: 'Let us therefore come boldly unto the throne of grace, that we may obtain mercy, and find grace to help in time of need.', point: 'Come to God boldly; his throne is a throne of grace.' },
  { book: 'Hebrews', ref: 'Hebrews 9:22', level: 3, text: 'And almost all things are by the law purged with blood; and without shedding of blood is no remission.', point: 'Forgiveness came at a cost: Jesus’ blood.' },
  { book: 'Hebrews', ref: 'Hebrews 10:25', level: 2, text: 'Not forsaking the assembling of ourselves together, as the manner of some is; but exhorting one another…', point: 'Keep meeting together and encouraging each other.' },
  { book: 'Hebrews', ref: 'Hebrews 11:7', level: 3, text: 'By faith Noah, being warned of God of things not seen as yet, moved with fear, prepared an ark to the saving of his house…', point: 'Noah built for rain he had never seen.' },
  { book: 'Hebrews', ref: 'Hebrews 12:1', level: 2, text: 'Wherefore seeing we also are compassed about with so great a cloud of witnesses, let us lay aside every weight, and the sin which doth so easily beset us, and let us run with patience the race that is set before us,', point: 'Drop the weights and run your race.' },
  { book: 'Hebrews', ref: 'Hebrews 12:2', level: 2, text: 'Looking unto Jesus the author and finisher of our faith; who for the joy that was set before him endured the cross, despising the shame, and is set down at the right hand of the throne of God.', point: 'Keep your eyes on Jesus, who finished the race.' },
  { book: 'Hebrews', ref: 'Hebrews 13:2', level: 3, text: 'Be not forgetful to entertain strangers: for thereby some have entertained angels unawares.', point: 'Welcome strangers; you never know who’s at the door.' },
  { book: 'Hebrews', ref: 'Hebrews 13:5', level: 2, text: 'Let your conversation be without covetousness; and be content with such things as ye have: for he hath said, I will never leave thee, nor forsake thee.', point: 'Contentment comes from God’s promise to stay.' },
  { book: 'James', ref: 'James 1:5', level: 1, text: 'If any of you lack wisdom, let him ask of God, that giveth to all men liberally, and upbraideth not; and it shall be given him.', point: 'Need wisdom for a decision? Ask God; he gives generously.' },
  { book: 'James', ref: 'James 1:22', level: 2, text: 'But be ye doers of the word, and not hearers only, deceiving your own selves.', point: 'Hearing the Bible is good; living it is the point.' },
  { book: 'James', ref: 'James 4:7', level: 1, text: 'Submit yourselves therefore to God. Resist the devil, and he will flee from you.', point: 'Stay close to God, and the enemy loses his grip.' },
  { book: 'James', ref: 'James 1:2', level: 2, text: 'My brethren, count it all joy when ye fall into divers temptations;', point: 'Trials can grow us, so there’s joy even in them.' },
  { book: 'James', ref: 'James 1:17', level: 2, text: 'Every good gift and every perfect gift is from above, and cometh down from the Father of lights, with whom is no variableness, neither shadow of turning.', point: 'Every good thing in your life comes from God.' },
  { book: 'James', ref: 'James 1:19', level: 2, text: 'Wherefore, my beloved brethren, let every man be swift to hear, slow to speak, slow to wrath:', point: 'Listen fast, speak slow, anger slower.' },
  { book: 'James', ref: 'James 2:17', level: 2, text: 'Even so faith, if it hath not works, is dead, being alone.', point: 'Real faith shows up in action.' },
  { book: 'James', ref: 'James 3:5', level: 3, text: 'Even so the tongue is a little member, and boasteth great things. Behold, how great a matter a little fire kindleth!', point: 'A small spark of words can start a big fire.' },
  { book: 'James', ref: 'James 4:8', level: 2, text: 'Draw nigh to God, and he will draw nigh to you. Cleanse your hands, ye sinners; and purify your hearts, ye double minded.', point: 'Take a step toward God and he comes near.' },
  { book: 'James', ref: 'James 4:10', level: 3, text: 'Humble yourselves in the sight of the Lord, and he shall lift you up.', point: 'God lifts up the humble.' },
  { book: 'James', ref: 'James 4:14', level: 3, text: 'Whereas ye know not what shall be on the morrow. For what is your life? It is even a vapour, that appeareth for a little time, and then vanisheth away.', point: 'Life is short like morning mist; live it for God.' },
  { book: 'James', ref: 'James 5:16', level: 3, text: '…The effectual fervent prayer of a righteous man availeth much.', point: 'Prayer is powerful.' },
  { book: '1 Peter', ref: '1 Peter 2:9', level: 2, text: 'But ye are a chosen generation, a royal priesthood, an holy nation, a peculiar people…', point: 'In Christ you are chosen and belong to God’s own people.' },
  { book: '1 Peter', ref: '1 Peter 5:7', level: 1, text: 'Casting all your care upon him; for he careth for you.', point: 'You can hand every worry to God because he truly cares.' },
  { book: '1 Peter', ref: '1 Peter 5:8', level: 2, text: 'Be sober, be vigilant; because your adversary the devil, as a roaring lion, walketh about, seeking whom he may devour:', point: 'Stay alert; the enemy is real, but Christ has already won.' },
  { book: '1 Peter', ref: '1 Peter 1:16', level: 3, text: 'Because it is written, Be ye holy; for I am holy.', point: 'Peter quoted Leviticus: God’s people reflect his holiness.' },
  { book: '1 Peter', ref: '1 Peter 2:24', level: 3, text: 'Who his own self bare our sins in his own body on the tree, that we, being dead to sins, should live unto righteousness: by whose stripes ye were healed.', point: 'Jesus carried our sins on the cross.' },
  { book: '1 Peter', ref: '1 Peter 3:15', level: 2, text: 'But sanctify the Lord God in your hearts: and be ready always to give an answer to every man that asketh you a reason of the hope that is in you with meekness and fear:', point: 'Be ready to explain your hope, gently.' },
  { book: '1 Peter', ref: '1 Peter 4:8', level: 3, text: 'And above all things have fervent charity among yourselves: for charity shall cover the multitude of sins.', point: 'Love covers a lot.' },
  { book: '1 Peter', ref: '1 Peter 4:10', level: 3, text: 'As every man hath received the gift, even so minister the same one to another, as good stewards of the manifold grace of God.', point: 'Use your gifts to serve others.' },
  { book: '2 Peter', ref: '2 Peter 3:9', level: 3, text: 'The Lord is not slack concerning his promise, as some men count slackness; but is longsuffering to us-ward, not willing that any should perish, but that all should come to repentance.', point: 'God’s patience is mercy, giving more people time to turn to him.' },
  { book: '2 Peter', ref: '2 Peter 1:21', level: 3, text: 'For the prophecy came not in old time by the will of man: but holy men of God spake as they were moved by the Holy Ghost.', point: 'Scripture came from God through people.' },
  { book: '2 Peter', ref: '2 Peter 3:8', level: 2, text: 'But, beloved, be not ignorant of this one thing, that one day is with the Lord as a thousand years, and a thousand years as one day.', point: 'God isn’t bound by our clocks.' },
  { book: '2 Peter', ref: '2 Peter 3:18', level: 3, text: 'But grow in grace, and in the knowledge of our Lord and Saviour Jesus Christ. To him be glory both now and for ever. Amen.', point: 'Keep growing in knowing Jesus.' },
  { book: '1 John', ref: '1 John 1:9', level: 1, text: 'If we confess our sins, he is faithful and just to forgive us our sins, and to cleanse us from all unrighteousness.', point: 'Honest confession meets complete forgiveness.' },
  { book: '1 John', ref: '1 John 4:4', level: 2, text: 'Ye are of God, little children, and have overcome them: because greater is he that is in you, than he that is in the world.', point: 'The One living in you is greater than anything you face.' },
  { book: '1 John', ref: '1 John 4:8', level: 2, text: 'He that loveth not knoweth not God; for God is love.', point: 'Love isn’t just something God does; it is who he is.' },
  { book: '1 John', ref: '1 John 1:7', level: 3, text: 'But if we walk in the light, as he is in the light, we have fellowship one with another, and the blood of Jesus Christ his Son cleanseth us from all sin.', point: 'Walking in the light brings fellowship and cleansing.' },
  { book: '1 John', ref: '1 John 2:15', level: 3, text: 'Love not the world, neither the things that are in the world. If any man love the world, the love of the Father is not in him.', point: 'Don’t let stuff steal your heart from God.' },
  { book: '1 John', ref: '1 John 3:1', level: 2, text: 'Behold, what manner of love the Father hath bestowed upon us, that we should be called the sons of God…', point: 'God calls you his child. What love!' },
  { book: '1 John', ref: '1 John 3:18', level: 3, text: 'My little children, let us not love in word, neither in tongue; but in deed and in truth.', point: 'Love is shown, not just said.' },
  { book: '1 John', ref: '1 John 4:18', level: 2, text: 'There is no fear in love; but perfect love casteth out fear: because fear hath torment. He that feareth is not made perfect in love.', point: 'God’s perfect love pushes fear out.' },
  { book: '1 John', ref: '1 John 4:19', level: 1, text: 'We love him, because he first loved us.', point: 'Our love is always a response to his.' },
  { book: '1 John', ref: '1 John 5:13', level: 3, text: 'These things have I written unto you that believe on the name of the Son of God; that ye may know that ye have eternal life…', point: 'You can know for sure you have eternal life.' },
  { book: '2 John', ref: '2 John 1:1', level: 3, text: 'The elder unto the elect lady and her children, whom I love in the truth; and not I only, but also all they that have known the truth;', point: 'A tiny letter showing that truth and love belong together.' },
  { book: '2 John', ref: '2 John 1:6', level: 3, text: 'And this is love, that we walk after his commandments. This is the commandment, That, as ye have heard from the beginning, ye should walk in it.', point: 'Love walks in God’s ways.' },
  { book: '2 John', ref: '2 John 1:12', level: 3, text: 'Having many things to write unto you, I would not write with paper and ink: but I trust to come unto you, and speak face to face, that our joy may be full.', point: 'Some things are better said face to face.' },
  { book: '3 John', ref: '3 John 1:2', level: 2, text: 'Beloved, I wish above all things that thou mayest prosper and be in health, even as thy soul prospereth.', point: 'A friend’s prayer that care for the soul comes first and the rest follows.' },
  { book: '3 John', ref: '3 John 1:4', level: 3, text: 'I have no greater joy than to hear that my children walk in truth.', point: 'Nothing made John happier than people walking with God.' },
  { book: '3 John', ref: '3 John 1:11', level: 3, text: 'Beloved, follow not that which is evil, but that which is good. He that doeth good is of God: but he that doeth evil hath not seen God.', point: 'Copy what is good.' },
  { book: 'Jude', ref: 'Jude 1:24', level: 3, text: 'Now unto him that is able to keep you from falling, and to present you faultless before the presence of his glory with exceeding joy,', point: 'God is able to keep you standing all the way to the end.' },
  { book: 'Jude', ref: 'Jude 1:3', level: 3, text: '…that ye should earnestly contend for the faith which was once delivered unto the saints.', point: 'The faith is worth standing up for.' },
  { book: 'Jude', ref: 'Jude 1:21', level: 3, text: 'Keep yourselves in the love of God, looking for the mercy of our Lord Jesus Christ unto eternal life.', point: 'Stay close to God’s love while you wait for Jesus.' },
  { book: 'Jude', ref: 'Jude 1:25', level: 3, text: 'To the only wise God our Saviour, be glory and majesty, dominion and power, both now and ever. Amen.', point: 'Jude ends with a burst of praise.' },

  // ---------- Revelation ----------
  { book: 'Revelation', ref: 'Revelation 3:16', level: 3, text: 'So then because thou art lukewarm, and neither cold nor hot, I will spue thee out of my mouth.', point: 'Jesus wants wholehearted followers, not half-hearted ones.' },
  { book: 'Revelation', ref: 'Revelation 3:20', level: 1, text: 'Behold, I stand at the door, and knock: if any man hear my voice, and open the door, I will come in to him, and will sup with him, and he with me.', point: 'Jesus knocks and waits; the door is yours to open.' },
  { book: 'Revelation', ref: 'Revelation 21:4', level: 1, text: 'And God shall wipe away all tears from their eyes; and there shall be no more death, neither sorrow, nor crying, neither shall there be any more pain…', point: 'The story ends with God making everything new and wiping every tear.' },
  { book: 'Revelation', ref: 'Revelation 1:8', level: 2, text: 'I am Alpha and Omega, the beginning and the ending, saith the Lord, which is, and which was, and which is to come, the Almighty.', point: 'Jesus is the first and the last letter of the story.' },
  { book: 'Revelation', ref: 'Revelation 1:18', level: 3, text: 'I am he that liveth, and was dead; and, behold, I am alive for evermore, Amen; and have the keys of hell and of death.', point: 'The risen Jesus holds the keys of death.' },
  { book: 'Revelation', ref: 'Revelation 2:10', level: 3, text: '…be thou faithful unto death, and I will give thee a crown of life.', point: 'Stay faithful; a crown of life is waiting.' },
  { book: 'Revelation', ref: 'Revelation 4:8', level: 3, text: '…and they rest not day and night, saying, Holy, holy, holy, Lord God Almighty, which was, and is, and is to come.', point: 'Heaven’s worship never stops.' },
  { book: 'Revelation', ref: 'Revelation 5:12', level: 2, text: 'Saying with a loud voice, Worthy is the Lamb that was slain to receive power, and riches, and wisdom, and strength, and honour, and glory, and blessing.', point: 'The Lamb who was slain is worthy of all praise.' },
  { book: 'Revelation', ref: 'Revelation 7:9', level: 3, text: 'After this I beheld, and, lo, a great multitude, which no man could number, of all nations, and kindreds, and people, and tongues, stood before the throne, and before the Lamb, clothed with white robes, and palms in their hands;', point: 'Every nation and language will worship Jesus together.' },
  { book: 'Revelation', ref: 'Revelation 12:11', level: 3, text: 'And they overcame him by the blood of the Lamb, and by the word of their testimony; and they loved not their lives unto the death.', point: 'Victory comes through Jesus’ blood and our testimony.' },
  { book: 'Revelation', ref: 'Revelation 19:16', level: 2, text: 'And he hath on his vesture and on his thigh a name written, KING OF KINGS, AND LORD OF LORDS.', point: 'Jesus’ name above every name.' },
  { book: 'Revelation', ref: 'Revelation 21:5', level: 2, text: 'And he that sat upon the throne said, Behold, I make all things new. And he said unto me, Write: for these words are true and faithful.', point: 'God’s plan ends with everything made new.' },
  { book: 'Revelation', ref: 'Revelation 22:20', level: 3, text: 'He which testifieth these things saith, Surely I come quickly. Amen. Even so, come, Lord Jesus.', point: 'The Bible’s last prayer: come, Lord Jesus.' },
];
